quests[64012] = { id = 64012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte vom Vorstoß des Todes", description = "Eure Bemühungen, den Fortschritt des Kerkermeisters zu stoppen, sind nicht unbemerkt geblieben. Wenn Ihr nach weiterer Macht für den nächsten Schritt sucht, kann ich Euch sicher dabei behilflich sein.", sourceObjective = "Sprecht mit Herzogin Mynx in der Zuflucht des Hüters in Korthia.", completion = "Eure Bemühungen, den Fortschritt des Kerkermeisters zu stoppen, sind nicht unbemerkt geblieben. Wenn Ihr nach weiterer Macht für den nächsten Schritt sucht, kann ich Euch sicher dabei behilflich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[64014] = { id = 64014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlundforschung", description = "Es bleibt nun noch eine Aufgabe, bevor die glorreiche Schlacht beginnen kann. Das Horn muss im Schlund verankert werden, damit sein Klang die Barriere, die dieses verderbte Reich umgibt, durchdringen kann.\n\nIch selbst weiß nicht, wie das zu bewerkstelligen ist. Sucht nach jemandem, der die Geheimnisse des Ortes versteht und Eure Hand sicher führen kann.\n\nDanica und ihre Schwestern werden auf den Ruf des Ilskahorns hören und geeilt kommen, wenn Ihr sie braucht, {name}.", sourceObjective = "Bittet Ve'nari, Euch dabei zu helfen, das Ilskahorn an den Schlund zu binden.", completion = "Ein imposantes Instrument habt Ihr da.\n\nEs scheint, die goldenen Federn waren den Aufwand wert, Schlundgänger. Ihr schuldet mir etwas. Schon wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[64015] = { id = 64015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Fleischwolf", description = "Bei all diesen Schlundgebundenen kriegt man richtig Lust auf Gemetzel!\n\nIch habe einen Plan, den Ihr sogar überleben könnt.\n\nSeid Ihr dabei?", sourceObjective = "Stellt den Schlundgebundenen eine Falle.", completion = "Buahahaha!\n\nSo viel Gemetzel, so viele Teile! Heute habt Ihr wirklich gut zugeschlagen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64016] = { id = 64016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charakterschleime", description = "Lehrling! Ich habe nach Euch gesucht.\n\nKevin war ein wundervoller Gehilfe bei unseren Experimenten, daher möchte ich auch meinen anderen Schleimen Assistenzarbeiten antrainieren.\n\nWas Schleimi betrifft, würde ich gerne wissen, ob er organische Materialien verschlingen und dadurch wachsen kann.", sourceObjective = "Helft Schleimi, seine Wachstumsfähigkeit an Splitterfellen am Zerfleischerausguck zu erproben.", completion = "Und, wie lief der Test? OH! Schleimi! Du bist ja riesig! Du bist sogar noch schöner als zuvor!", sourceObjectiveStatus = "unverified-source-field" }
quests[64017] = { id = 64017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charakterschleime", description = "Lehrling! Ich habe nach Euch gesucht.\n\nKevin war ein wundervoller Gehilfe bei unseren Experimenten, daher möchte ich auch meinen anderen Schleimen Assistenzarbeiten antrainieren.\n\nWas Bluup betrifft, würde ich gerne wissen, ob sein Schleim sich vermehren kann. Nehmt ihn mit Euch und sucht diese Bären. Befehlt ihm, den Lebensformen seinen Schleim zu injizieren, und findet heraus, was geschieht.", sourceObjective = "Helft Bluup, seine Vermehrungsfähigkeit am Zerfleischerausguck zu erproben.", completion = "Und, wie lief der Test? OH! Seht sie Euch nur an! Die sind ja so niedlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[64018] = { id = 64018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gewicht des Steins", sourceObjective = "Unterstützt die Steinlegion bei den Vorrats- und Animalieferungen.", completion = "Ihr habt es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[64040] = { id = 64040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heile, heile, Segen", description = "Die Schlundgebundenen stürzen sich weiter auf unsere Streitkräfte am Archiv. Auf beiden Seiten gibt es heftige Verluste. Da müssen wir helfen!\n\nNehmt das hier und heilt damit alle verwundeten Paktverbündeten, die Ihr dort draußen entdeckt. Ich habe es mit Mikanikos' Hilfe erschaffen. Es nutzt Anima und sollte alle heilen können. Selbst die Steingeborenen oder die Maldraxxi.", sourceObjective = "Heilt 10 verwundete Paktverbündete.", completion = "Wie wundervoll! Es ist eine große Erleichterung, dass es unseren Verbündeten besser geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[64042] = { id = 64042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituale der Nacht", description = "Tyrande bleibt nicht mehr viel Zeit. Wir müssen schnell handeln.\n\n<Ysera runzelt besorgt die Stirn.>\n\nWir hatten gehofft, noch mehr Nachtkrieger zu versammeln, aber jetzt müssen wir einfach mit denen weitermachen, die wir schon haben, und hoffen, dass es ausreicht.\n\n<Ysera schüttelt den Kopf und blickt fest entschlossen wieder auf.>\n\nBevor wir beginnen, müssen wir noch die Vorbereitungen für das Ritual abschließen. Bringt bitte diese letzten Sachen mit und trefft uns dann am Hain.", sourceObjective = "Helft bei den Vorbereitungen und bei dem Ritual.", progress = "Gut, wir können beginnen.", completion = "Jetzt, wo alles vorbereitet ist, kann es losgehen. Ich hoffe nur, dass es für Tyrande nicht schon zu spät ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[64043] = { id = 64043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiler gesucht", description = "Es gibt zu viele Verwundete auf dem Schlachtfeld!\n\nNicht jeder lässt sich durch Draufklopfen wieder hinbiegen. Wir brauchen mehr Heiler.\n\nNehmt mein Gerät und sorgt dafür, dass die Verwundeten wieder auf die Beine kommen!", sourceObjective = "Heilt 10 verwundete Paktverbündete im Quorum des Suchers.", completion = "Das hat ihnen wieder auf die Beine geholfen!\n\nAuch die kleinste Hilfe unterstützt uns im Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[64065] = { id = 64065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokale Reagenzien", description = "Korthia ist ein merkwürdiger Ort. Die Tiere hier sind anders, was vermutlich mit der Ausstrahlung des Archivs und dessen Inhalten zu tun hat.\n\nSeid Ihr bereit, ein wenig zu experimentieren? Erst brauchen wir allerdings einen Vorrat an Reagenzien.\n\nIn der Nähe des Quorums des Suchers solltet Ihr Splitterfelle, Gromits und Klingenschwingen finden. Passt auf ihre Nadeln auf!", sourceObjective = "Sammelt 8 Splitterfellkrallen, 6 Gromitfüße und 1 Klingenschwingennadeln für Seuchenerfinder Marileth in Korthia.", progress = "Habt Ihr Lust, mein neuestes Experiment auszuprobieren? Vermutlich wird es Euch nicht umbringen.", completion = "Diese Nadel ist so lang und makellos! Gut gemacht, Lehrling. Ich kann es gar nicht erwarten, mit den neuen Tests zu beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64070] = { id = 64070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrott wird wieder flott", description = "Unsere Armee benötigt stets weitere Waffen, Rüstungen und Truppen. Immer.\n\nSicher, wir erhalten Verstärkung, aber so wie es läuft, kann ich nicht alle ordentlich ausrüsten. Vor allem nicht ohne richtige Schmiede und Helfer.\n\nAlso müssen wir uns mit der nächstbesten Sache abfinden. Bringt mir bitte jegliches Altmetall, das ihr bei den Schlundgebundenen findet. Ich werde schon einen Weg finden, es zu Waffen zu machen.", sourceObjective = "Sammelt 12 Altmetall der Schlundgebundenen.", progress = "Eines Tages werde ich in einer Kampagne kämpfen, in der wir ausreichend mit Ausrüstung und Vorräten versorgt sind. Das wird der einfachste Krieg aller Zeiten sein.", completion = "Nun, es sind nicht gerade die feinsten Materialien, aber es wird schon gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64080] = { id = 64080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geerdet", description = "Ich höre die Flügel der Schlundgebundenen im Himmel über uns, wie sie uns verspotten.\n\nDoch am Boden kann man Vögeln die Flügel stutzen.\n\nNehmt meinen Speer und zeigt mir, wie gut Ihr zielen könnt. Zerrt ein paar von ihnen aus den Lüften und streckt sie nieder.\n\nAber benutzt auch wirklich den Speer und watschelt nicht einfach herum, bis sie Euch auf den Boden folgen. Darum geht es nicht.\n\nIch will sehen, wie Ihr sie aus dem Himmel holt.", sourceObjective = "Benutzt Korayns Wurfspeer, um 4 schlundgebundene Herolde aufzuspießen.", completion = "Eine wahre Befriedigung zu sehen, wie Ihr diesen fliegenden Schlundgebundenen die Flügel stutzt.\n\nDas habt Ihr gut gemacht, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[64083] = { id = 64083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktiker von Sündensturz", description = "Sündensturz erhält mehr Respekt, als es sich Denathrius je hätte erhoffen können! Das ist alles Eurem Einsatz zu verdanken, {name}.\n\nZo'Sorg wünscht ein weiteres Mal Eure Anwesenheit in Oribos. Geht sofort.\n\nWir möchten nicht die Gunst des Kartells Zo riskieren! Das Vertrauen eines Mittlerklans ist nicht leicht verdient.\n\nVielleicht haben sie noch mehr Belohnungen, die sie Euch zuteilkommen lassen möchten.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Wie ich sehe, haben sich Eure Kampffähigkeiten weiter verbessert. Ich gehe davon aus, dass Ihr guten Nutzen aus unserem letzten Angebot gezogen habt?\n\nZo'dash wurde angewiesen, Euch nun all seine Dienstleistungen zuteilkommen zu lassen. Ich freue mich darauf, ihre Auswirkungen auf Eure Leistung zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64084] = { id = 64084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktiker der Nekrolords", description = "Ihr habt den Nekrolords große Ehre erwiesen. Solche Ehrerweisung erregt wiederum die Aufmerksamkeit anderer.\n\nZo'Sorg wünscht ein weiteres Mal Eure Anwesenheit in Oribos. Geht sofort.\n\nWir möchten nicht die Gunst von Kartell Zo riskieren! Das Vertrauen eines Mittlerklans ist nicht leicht verdient.\n\nVielleicht hat er noch mehr Belohnungen, die er Euch zuteilwerden lassen möchte.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Wie ich sehe, haben sich Eure Kampffähigkeiten weiter verbessert. Ich gehe davon aus, dass Ihr guten Nutzen aus unserem letzten Angebot gezogen habt?\n\nZo'dash wurde angewiesen, Euch nun all seine Dienstleistungen zuteilkommen zu lassen. Ich freue mich darauf, ihre Auswirkungen auf Eure Leistung zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64085] = { id = 64085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktiker der Nachtfae", description = "Eure Tapferkeit hat es dem Ardenwald ermöglicht, wieder zu wachsen. Das hat auch erneut die Aufmerksamkeit von Mittlern auf sich gezogen.\n\nZo'Sorg wünscht ein weiteres Mal Eure Anwesenheit in Oribos. Geht sofort.\n\nWir möchten nicht die Gunst des Kartells Zo riskieren. Das Vertrauen eines Mittlerklans ist nicht leicht verdient.\n\nVielleicht haben sie noch mehr Belohnungen, die sie Euch zuteilwerden lassen möchten.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Wie ich sehe, haben sich Eure Kampffähigkeiten weiter verbessert. Ich gehe davon aus, dass Ihr guten Nutzen aus unserem letzten Angebot gezogen habt?\n\nZo'dash wurde angewiesen, Euch nun all seine Dienstleistungen zuteilkommen zu lassen. Ich freue mich darauf, ihre Auswirkungen auf Eure Leistung zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64086] = { id = 64086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktiker der Kyrianer", description = "Seht Euch um, {name}. Die Elysische Feste zeigt in aller Deutlichkeit, wie weit wir gekommen sind, dank Euch.\n\nZo'Sorg wünscht ein weiteres Mal Eure Anwesenheit in Oribos. Geht sofort.\n\nWir möchten nicht die Gunst von Kartell Zo riskieren. Das Vertrauen eines Mittlerklans ist nicht leicht verdient.\n\nVielleicht hat er noch mehr Belohnungen, die er Euch zuteilwerden lassen möchte.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Wie ich sehe, haben sich Eure Kampffähigkeiten weiter verbessert. Ich gehe davon aus, dass Ihr guten Nutzen aus unserem letzten Angebot gezogen habt?\n\nZo'dash wurde angewiesen, Euch nun all seine Dienstleistungen zuteilkommen zu lassen. Ich freue mich darauf, ihre Auswirkungen auf Eure Leistung zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64089] = { id = 64089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tees und Tinkturen", description = "Wie herrlich! Was für ein hübscher Flecken Natur.\n\nHabt Ihr schon die örtlichen Aufgüsse probiert? Vielleicht einen angenehmen Kräutertee? Nicht? Nun, dann lasst uns das gemeinsam tun! Seht Euch ein wenig um und bringt mir alle Kräuter, die... interessant aussehen.\n\nEin nettes Tässchen Tee und dann machen wir uns an die Arbeit. Ich warte hier.", sourceObjective = "Sammelt 12 mögliche Teezutaten.", progress = "Tubbins! Gubbins! Was habt Ihr denn schon wieder vor? Ihr stört doch nicht schon wieder die Nachtfae, oder?", completion = "Meine Güte! Die meisten dieser Kräuter habe ich noch nie gesehen. Hm, dieses schwarze sieht recht gefährlich aus. Das grüne wirkt vielversprechend. Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[64090] = { id = 64090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgequetscht", description = "Unser vermisster Kollege hat sich wegschleppen lassen und wird sicher gerade mächtig ausgequetscht. Glücklicherweise hab ich alles aufm Schirm.\n\nWir schleichen uns leise rein, als würden wir da arbeiten, finden Euren Elch, gucken keinem Fangzahn in die Augen und meißeln uns raus, als wären wir ein paar Steinmetze. Klaro?", sourceObjective = "Begebt Euch an den Ort, an dem Knüppelfratze Huln vermutet, und passt Euch an.", progress = "Na, das ist ja aufregend!", completion = "Klingt, als würde Huln nicht mehr viel Zeit bleiben!", sourceObjectiveStatus = "unverified-source-field" }
quests[64091] = { id = 64091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fragwürdiges Angebot", description = "<Der Schreckenslord blickt Euch an und möchte reden. Ihr seht zu Euren Begleitern hinüber. Mondbeere schickt Euch mit einem schelmischen Grinsen voraus. Ihr tretet so nahe heran, wie Ihr es wagt.>\n\nBefreit mich aus diesem Gefängnis, <Sterblicher/Sterbliche>, und ich werde Euch wohlgesonnen sein. Ich stehe mit Mächten in Verbindung, die größer sind als diese ärmlichen Puppen und ihre Meister. Sie verstehen nichts von den wahren Kräften, die hier am Werk sind.\n\nIch brauche nur die Zeichen der Bindung, die mich hier festhalten. Um den Rest... kann ich mich kümmern.\n\nBefreit mich und Ihr werdet unvorstellbare Macht erlangen.", sourceObjective = "Beschafft die Zeichen der Bindung.", completion = "Wenn er geschnappt wurde, weiß ich, wo die ihn hingebracht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[64092] = { id = 64092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd auf Huln", description = "Huln ist irgendwo hier, aber die Steinhauerin lässt wegen der, äh, kürzlichen Ärgernisse mit den Schreckenslords niemanden in ihr Gebiet. Die Wächter lassen niemanden rein, und wer fehl am Platze aussieht, wird rausgeworfen.\n\nZum Glück für Huln haben Knüppelfratze und ich uns einen unfehlbaren Plan einfallen lassen!\n\nWir müssen nur so aussehen, als gehörten wir da hin. Dann können wir uns umhören und Huln finden. Ein Kinderspiel!", sourceObjective = "Legt eine Verkleidung an und durchsucht die Herrschaftsburg nach Huln Hochberg. Geht dabei den Wachen aus dem Weg.", completion = "Ich bin gerade mit diesem Schreckenslordabschaum beschäftigt. Findet etwas Nützliches zu erledigen, bevor die Steinhauerin wütend wird. Glaubt mir, Ihr wollt sie nicht wütend erleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[64101] = { id = 64101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der richtige Umgang", sourceObjective = "Sammelt 5 verlorene Animagefäße.", completion = "Eine gewaltige Menge Anima. Das wird den Bediensteten sehr dabei helfen, hier alles neu aufzubauen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[64103] = { id = 64103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewährte Methoden", sourceObjective = "Tötet Moros, Oizys und Apate, Kommandanten der Schlundgebundenen.", completion = "Ein Machtvakuum kann einer Armee mehr Schaden zufügen als jede Bombe oder Schlacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[64104] = { id = 64104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die armen Tierchen", description = "Die Wildtiere in Korthia haben viel durchgemacht. Einige finden nicht mehr genug zum Essen!\n\nIch habe ein wenig Nahrung beiseitegelegt, um sie mit ihnen zu teilen.\n\nIch fürchte jedoch, dass sie zu scheu sind, um uns zu trauen. Das kann man ihnen auch kaum übel nehmen!\n\nHier, nehmt diese Leckereien und versucht, Euch ihnen so weit zu nähern, dass Ihr sie richtig füttern könnt. Selbst die kleinen Wesen sind wirklich wichtig.", sourceObjective = "Nähert Euch hungrigen Gromits in Korthia und füttert sie.", completion = "Ihr konntet einige von ihnen füttern? Wie wundervoll!\n\nIch werde schon Essen fürs nächste Mal sammeln. Ich hoffe, dass wir diesem Ort eines Tages zur Heilung verhelfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[64106] = { id = 64106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinte Bemühungen", description = "Ihr habt in Eurem Pakt und auch anderenorts in den Schattenlanden starke Verbündete gefunden. Wegen dieser Verbindung haben sie sich entschlossen, unser Ziel unterstützen.\n\nSie sind bereit, an unserer Seite zu kämpfen, während wir unseren Marsch in den Schlund beginnen.\n\nJeder Pakt wird sich aus einem anderen Bereich auf den Kerkermeister stürzen. Helft ihnen, dieses bedrohliche Land nach jenen zu durchsuchen, die Zovaal dienen, damit wir seinen anwachsenden Einfluss beenden können.", sourceObjective = "Helft den Pakten beim Angriff auf die Streitkräfte des Kerkermeisters im Schlund.", completion = "Gebt nicht nach, {name}. Dies ist nur die erste von vielen Schlachten, die uns bevorstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64129] = { id = 64129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Wilden Jagd", description = "Seit ich der Wilden Jagd beigetreten bin, habe ich so viel darüber gelernt, wie man kämpft und die Reiche verteidigt.\n\nIch gebe zu, ich lerne immer noch, aber es freut mich sehr, dies an Eurer Seite und der meines Runenhirschfreundes Aldermeigh zu tun.\n\nAldermeigh wird darauf trainiert, mit der Tapferkeit der Vorkai in die Schlacht zu stürmen, doch er braucht noch mehr Übung. Würdet Ihr mit ihm ausreiten und all die Schlundgebundenen niedertrampeln, die sich Euch in den Weg stellen?", sourceObjective = "Steigt auf Aldermeigh auf und tötet Schlundgebundene in Korthia.", completion = "Ihr und Aldermeigh seid ein großartiges Gespann! Vielen Dank, dass Ihr ihn mitgenommen und so viele Schlundgebundene zur Strecke gebracht habt.\n\nEines Tages werde auch ich mit der Wilden Jagd reiten, und dann werden wir viel Unrecht wiedergutmachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64131] = { id = 64131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[64138] = { id = 64138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[64159] = { id = 64159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltene Vorräte zurückerobern", description = "Die Rebellen haben Vorräte aus den umliegenden Lagern gestohlen.\n\nIhr habt bewiesen, dass Ihr solche Situationen lösen könnt. Ich vertraue darauf, dass Ihr uns auch helfen könnt, diese Situation zu lösen.", sourceObjective = "Holt Vorräte aus den behelfsmäßigen Lagern auf der anderen Seite des Flusses zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[64162] = { id = 64162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rituelle Rivalen", description = "Ein weiterer rivalisierender Khan hat sich aus den Rebellenstämmen erhoben.\n\nIch würde mich selbst darum kümmern, aber ich muss die Dinge hier im Auge behalten.\n\nKann ich darauf vertrauen, dass Ihr ihnen eine Lektion erteilt?", sourceObjective = "Findet und besiegt den Khan der Rebellen in den behelfsmäßigen Lagern auf der anderen Seite des Flusses.", sourceObjectiveStatus = "unverified-source-field" }
quests[64163] = { id = 64163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache an den Abtrünnigen", description = "Rebellenklans haben Anspruch auf einige unserer Lager auf der anderen Seite des Flusses erhoben.\n\nSolch aufrührerischen Umtriebe müssen unterbunden werden.\n\nDarf ich darauf vertrauen, dass Ihr in der Lage seid, diesen Rebellen in meinem Namen eine Lektion zu erteilen?\n\nIn den Lagern herrscht zudem ein heilloses Chaos, aber ignoriert das vorerst. Wir können das später klären, wenn die Ordnung wiederhergestellt ist.", sourceObjective = "Findet und besiegt die Krieger der Zentaurenrebellen in den behelfsmäßigen Lagern auf der anderen Seite des Flusses.", sourceObjectiveStatus = "unverified-source-field" }
quests[64166] = { id = 64166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In memoriam", description = "Als der Kerkermeister sich Korthia gegriffen und in den Schlund gezerrt hat, hat er so viel Zerstörung angerichtet. Nicht nur an Gebäuden und Bergen, auch an den Leuten dort.\n\nSie hatten Leben, Hoffnungen, Erinnerungen.\n\nIch kann nicht glauben, dass sie alle fort sind. Vielleicht verweilt noch etwas dort, das wir retten können.\n\nNehmt einen Teil meiner Macht. Versucht, damit die Erinnerungen zu sammeln. Bringt sie mir zurück, und ich werde sie bewahren.\n\nNiemand sollte vergessen werden.", sourceObjective = "Sammelt korthianische Erinnerungen mithilfe der vergänglichen Schwingen.", completion = "Ich danke Euch, {name}. Ich werde dafür sorgen, dass man sich um diese Erinnerungen kümmert.\n\nIch frage mich, wie es wohl gewesen wäre, als eine dieser Seelen hier zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[64167] = { id = 64167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierdetektiv", description = "Ich bin so froh, dass Ihr hier seid, {name}!\n\nIch erwarte eine Lieferung mit Haustierbedarf und neuen Haustieren, aber mein Vertriebsmanager Zantini hat sich nicht gemeldet. Ich glaube, da stimmt etwas nicht.\n\nMein Laden wird schon eine ganze Weile von zwielichtigen Leuten beobachtet. Ich kann aber den Laden nicht verlassen, um ihnen zu folgen. Ihr könnt das.\n\nNehmt meine Katze Fiona und findet diese verborgenen Spione.", sourceObjective = "Untersucht Dalaran mithilfe von Breannis spezieller Spionfängerkatze Fiona.", completion = "Also gibt es eine Gruppe purpurner Haustierfanatiker im Auge Azsharas?", sourceObjectiveStatus = "unverified-source-field" }
quests[64168] = { id = 64168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Spore von Marasmius", sourceObjective = "Uns nach Hause bringen?", sourceObjectiveStatus = "unverified-source-field" }
quests[64169] = { id = 64169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ella", sourceObjective = "Ella ist wieder mit ihrer Larve zusammen. Vielleicht solltet Ihr ihnen ein gutes Zuhause bieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64170] = { id = 64170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: ELGU - 007", sourceObjective = "Energieversorgung wiederhergestellt. Erwarte Eingabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[64171] = { id = 64171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kiaranyka", sourceObjective = "Ich danke Euch, Schlundgänger. Meine Aspirantin wird es zu würdigen wissen. Ich würde Euch gern bei Eurer Aufgabe beistehen, wenn Ihr es gestattet.", sourceObjectiveStatus = "unverified-source-field" }
quests[64172] = { id = 64172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ryuja Schockfaust", sourceObjective = "Das hat Spaß gemacht. Lasst uns das irgendwann wiederholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64173] = { id = 64173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Kinessa die Aufnahmefähige", sourceObjective = "Ich denke, wir sollten jetzt gehen. Und wir sollten mit niemandem darüber sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64174] = { id = 64174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Schankgriffel", sourceObjective = "So, jetzt muss ich mit dem Tablett aber wieder ans Werk. Soll ich Euch vielleicht irgendwas servieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[64175] = { id = 64175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lassik Gratkrümmer", sourceObjective = "Benötigen Eure Kollegen vielleicht Hilfe? Ich könnte mich bestimmt nützlich machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64184] = { id = 64184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisster Freund" }
quests[64185] = { id = 64185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ella wobei helfen?" }
quests[64186] = { id = 64186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ELGU - 007s vermisster Energiekern" }
quests[64187] = { id = 64187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kiaranykas Suche" }
quests[64188] = { id = 64188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ryujas Vorräte" }
quests[64189] = { id = 64189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinessas Unterstützung" }
quests[64190] = { id = 64190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schankgriffels Tablett" }
quests[64191] = { id = 64191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lassiks Ausrüstung" }
quests[64194] = { id = 64194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsprototyp", description = "Als Oberster Schmied versuche ich immer, was besser zu machen!\n\nAber die größten Zenturionen sind viel zu groß. Lassen sich nicht einfach nach Korthia bringen. Hab das Problem aber gelöst. Hier ist Atleos, Feldkolossprototyp, Frontkämpfer der Kyrianer! \n\nEr muss noch getestet werden. Solange, bis er perfekt auf mächtige Gegner vorbereitet ist.\n\nGeht und nehmt Atleos, um eine große Schlundbestie zu besiegen! Drückt auf alle Knöpfe!", sourceObjective = "Benutzt den Atleosprototyp am Windgepeitschten Nistgipfel, um Kraxis zu besiegen.", completion = "Ha! Ein perfekter Sieg. Atleos kehrt zurück und Ihr auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[64196] = { id = 64196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tierliebe", description = "Es klingt, als würde eine Gruppe Haustierwilderer im Auge Azsharas Ärger bereiten. Die Flugroute meines Versorgungsverwalters führt genau darüber hinweg!\n\nZantini und seine Haustiere, Stringfellowe und Flinky IV, waren auf dem Rückweg, und sie hatten neben anderen Tieren und Vorräten auch einen seltenen Murlocbegleiter dabei.\n\n{name}, bitte findet erst einmal Zantini und seine Haustiere. Helft ihnen. Dann können wir versuchen, die Tiere und Vorräte zurückzuholen.", sourceObjective = "Findet Zantini und seine Haustiere entlang der Küste im Auge Azsharas und helft ihnen.", completion = "Danke für die Rettung, mein Freund. Stringfellowe, Flinky IV und ich sind Euch wirklich dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[64202] = { id = 64202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Hand gehen", description = "Eure Macht, <Schlundgänger/Schlundgängerin>... Sie kommt selbst der meinen gleich, als Zovaal mich noch nicht von meinem Körper getrennt hatte.\n\nDies ist nur ein kleiner Teil von mir selbst, doch er reicht mehr als aus...\n\nErlaubt mir, Euch bei Euren Bemühungen gegen Zovaal zu unterstützen. Auf diese Weise werde ich meine Rachsucht stillen.", sourceObjective = "Nehmt Nilganihmahts Hilfe an.", completion = "<Die fünf Ringe strahlen und vereinigen ihre Macht zu einem kleinen Ring, der perfekt auf Euren Finger passen würde.>\n\n<Nilganihmahts Stimme dröhnt in Eurem Kopf.>\n\nVerlassen wir diesen Ort und ringen wir Zovaal gemeinsam nieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[64203] = { id = 64203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Küstenwache", description = "Ich war fast am Ende meines Versorgungsflugs, als wir abgeschossen wurden! Sie haben die Haustiere mitgenommen, doch die Vorräte wurden hier über den Strand verstreut.\n\nIch weiß nicht, was sie vorhaben, aber ich weiß, dass wir unsere Vorräte brauchen. Wir beide sind nicht gerade unauffällig... aber bei Flinky IV werden die Piraten sich nicht gleich verstecken. Er kann die Vorräte einsammeln, während Stringfellowe den Bereich aus der Luft überwacht.\n\nFlinky mag Euch, also redet einfach mit ihm und versucht, die schwelenden Vorräte zu sammeln, bevor alles verbrannt ist.", sourceObjective = "Sammelt mit Flinky IVHaustierbedarf entlang der Küste im Auge Azsharas.", progress = "Vorräte fehlen uns immer.", completion = "Wir haben die Vorräte wieder. Jetzt ist es an der Zeit, unsere Tiere zu holen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64210] = { id = 64210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kiste der Zahllosen Dinge", description = "Ah, <Schlundgänger/Schlundgängerin>, natürlich. Bald werde ich fort sein, für immer verloren an diesen Ort, doch Ihr werdet seine Hallen weiter beschreiten, ungebrochen!\n\nEs war immer mein größtes Ziel, mithilfe dieser Kiste die Oberhand zu gewinnen. Doch leider habe ich meine eigenen Fähigkeiten überschätzt.\n\nSicher überschätze ich die Euren nicht. Nehmt die Kiste. Erweist Euch ihr als würdig.", sourceObjective = "Bringt die Kiste der Zahllosen Dinge zum Runenmetz.", progress = "Ah, Ihr seid zurück!", completion = "Ah... ein interessantes Gerät. Es wird hilfreich sein, es an diesem Ort zu verankern.", sourceObjectiveStatus = "unverified-source-field" }
quests[64211] = { id = 64211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchgang im Dunkel", description = "Ich fürchte, unsere Pläne, Zovaal aufzuhalten, wurden vereitelt, <Sterblicher/Sterbliche>.\n\nJemand hat ein Portal in ein verbotenes Reich geöffnet... und der Verbannte hat eine Macht wiedererlangt, die ihm vor langer Zeit genommen wurde.\n\nIch spüre, dass Eure Verbündeten aus dem Sanktum der Herrschaft zurückkehren. Ich muss ganz genau wissen, was dort geschehen ist.", sourceObjective = "Sprecht mit Jaina und erlebt das Ende der Schlacht in Torghast mit.", completion = "<Jaina scheint traurig, aber fest entschlossen.>\n\nEs gibt immer noch Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[64212] = { id = 64212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchgang im Dunkel", description = "Ich fürchte, unsere Pläne, Zovaal aufzuhalten, wurden vereitelt, <Sterblicher/Sterbliche>.\n\nJemand hat ein Portal in ein verbotenes Reich geöffnet... und der Verbannte hat eine Macht wiedererlangt, die ihm vor langer Zeit genommen wurde.\n\nIch spüre, dass Eure Verbündeten aus dem Sanktum der Herrschaft zurückkehren. Ich muss ganz genau wissen, was dort geschehen ist.", sourceObjective = "Sprecht mit Thrall und erlebt das Ende der Schlacht in Torghast mit.", completion = "<Thralls Stirn liegt in tiefen Falten.>\n\nWir dürfen dem Kerkermeister nicht den Sieg überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64213] = { id = 64213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Symbol der Hoffnung", description = "Bevor Anduin dem Kerkermeister durch das Portal gefolgt ist, ließ er etwas fallen.\n\nIch glaube nicht, dass das zum Plan des Kerkermeisters gehört hat. Es muss ein Zeichen sein, dass Anduin immer noch Herr seiner eigenen Seele ist!\n\n<Jaina öffnet ihre Hand, um Euch einen goldenen Kompass zu zeigen.>\n\nDer hier war Anduin sehr wichtig. Ich fühle darin seine Anwesenheit.\n\nWir müssen herausfinden, warum er ihn für uns zurückgelassen hat.", sourceObjective = "Unterstützt Jaina bei der Untersuchung von Anduins Kompass.", completion = "<Tränen laufen über Jainas Gesicht.>\n\nWir dürfen ihn nicht verlieren, {name}. Um keinen Preis.", sourceObjectiveStatus = "unverified-source-field" }
quests[64214] = { id = 64214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Symbol der Hoffnung", description = "Bevor Anduin dem Kerkermeister durch das Portal gefolgt ist, ließ er etwas fallen.\n\nIch weiß nicht, was es war, aber Jaina hat es aufgehoben. Vielleicht war es ein Zeichen, dass sich Anduin noch immer dem Kerkermeister widersetzt!\n\nWir müssen herausfinden, was das für ein Objekt war und warum der junge König es für uns zurückließ.", sourceObjective = "Helft bei der Untersuchung von Anduins Kompass.", completion = "Anduin Wrynn hat solch ein Schicksal nicht verdient.\n\nWir müssen ihn retten, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[64215] = { id = 64215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf leisen Pfoten", description = "Während Flinky IV Vorräte gesammelt hat, war Stringfellowe auf Erkundungsmission im restlichen Auge Azsharas.\n\nScheint, als wäre da ein Riesenhaufen Piraten im Westen. Da werden bestimmt auch die Haustiere sein.\n\nAlso geht dorthin und rettet die Haustiere.", sourceObjective = "Beschafft die Schlüssel von den Purpursegelpiraten an der westlichen Küste im Auge Azsharas. Befreit danach die Haustiere.", progress = "Habt Ihr sie gefunden, {name}?", completion = "Gute Arbeit bei der Befreiung der Haustiere, {name}.\n\nAber es fehlt noch immer jede Spur von Gurgl.", sourceObjectiveStatus = "unverified-source-field" }
quests[64216] = { id = 64216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turmwissen", description = "Die verwobene Macht dieser Kiste kann nur freigesetzt werden, wenn man ihr Stolz und Erinnerungen zuführt. In sie sind Beschwörungsformeln eingewebt, die ich in den anderen Reichen gesehen habe. Sie werden verwendet, um eine Seele zu schröpfen oder zu konditionieren. Diese... Monstrosität... hat diese Werkzeuge der Erlösung und Ehre benutzt, um ein Schloss zu erschaffen.\n\nWährend Ihr die Stockwerke von Torghast in Angriff nehmt, werden Euer Können, Eure Geschwindigkeit und Eure Effizienz das Turmwissen vermehren. Die Kiste kann damit genährt werden.\n\nFührt ihr diese Dinge zu, um die ihr innewohnenden Kräfte zu erhalten.", sourceObjective = "Stellt die Kiste der Zahllosen Dinge in Torghast auf.", progress = "<Die Kiste der Zahllosen Dinge brummt vor Energie.>", completion = "<Die Kiste hungert und sucht in Euren Erinnerungen an Torghast nach vergangenen Taten, um sich davon zu nähren.>", sourceObjectiveStatus = "unverified-source-field" }
quests[64218] = { id = 64218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr von nah und fern", description = "In Bezug auf den Kerkermeister haben wir alles getan, was wir konnten.\n\nEs gibt noch andere Dinge, um die wir uns kümmern müssen. Zum Beispiel die Verschlingerrisse, die sich vor Kurzem im Osten geöffnet haben! \n\nWenn wir sie nicht aufhalten, werden diese Bestien hier alles zerstören.\n\nHelft Ihr mir, dem ein Ende zu machen, {name}?", sourceObjective = "Untersucht die Felder der Genesis.", completion = "Jemand da drinnen benötigt unsere Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[64219] = { id = 64219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine geheimnisvolle Stimme", description = "So viel Zerstörung. Die Verschlinger sind unersättlich.\n\nIch hoffe, die Kreatur, die wir gehört haben, ist nicht schwer verletzt.\n\nDiese Tür lässt sich nicht auf normale Weise öffnen. Vielleicht können wir uns gemeinsam einen Weg hinein erzwingen!\n\nWas auch immer auf der anderen Seite ist, braucht unsere Hilfe!", sourceObjective = "Betretet die Wiege der Naszenz.", progress = "Wer immer da drinnen ist... Wir müssen helfen!", completion = "Wir sind zu spät... Aber wir dürfen die Hoffnung nicht aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[64223] = { id = 64223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kern der Angelegenheit", description = "Sie ist gestürzt, aber sie scheint noch am Leben zu sein. Es muss etwas geben, das wir tun können, um ihr zu helfen.\n\nLasst uns sehen, ob die Erleuchteten etwas wissen. Ich werde einen Weg finden, um sie zu transportieren, und treffe Euch dann in der Zuflucht wieder.", sourceObjective = "Sprecht mit dem Ältesten Kreth in der Zuflucht.", progress = "Hoffentlich kommen wir nicht zu spät.", completion = "Das war... nicht hilfreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[64224] = { id = 64224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem Unbekannten", description = "Wenn die Ältesten uns nicht helfen wollen, müssen wir jemand anderen finden.\n\nDieser andere Erleuchtete, Firim, hatte mehr Interesse an den Automas.\n\nEr hat gesagt, er hätte sich von seiner Familie entfremdet. Irgendjemand in der Zuflucht muss etwas über ihn wissen.\n\nSeht Euch im Lager nach Hinweisen auf Firims Aufenthaltsort um. Ich versuche noch einmal, die Ältesten zum Reden zu bringen.", sourceObjective = "Sucht in der Zuflucht nach Informationen über Firim.", progress = "Habt Ihr etwas gefunden?", completion = "Die Ältesten weigern sich, etwas über Firim zu sagen.\n\nIch hoffe, Ihr konntet etwas herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[64225] = { id = 64225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Firim", description = "Ihr habt etwas gefunden? Was für ein Glück! Darf ich den Brief mal sehen?\n\nAha, ein Erleuchteter namens Xevveth hat gehört, dass Firim zuletzt westlich der Schmiede der Nachleben gesehen wurde, und sich aufgemacht, um dort nach ihm zu suchen.\n\nAuch wir sollten unsere Suche dort beginnen.", sourceObjective = "Findet Firim.", completion = "Diese Assassinen sind hinter mehr als nur meinem Leben her. Sie wollen meine Forschung stehlen! Sie dürfen sie nicht in die Finger bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64226] = { id = 64226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheitsvorkehrungen", description = "In Anbetracht der Tatsache, dass Ihr in mein Haus eingedrungen seid, scheint es, dass die versteckten Fallen, die ich um die Höhle herum aufgestellt habe, nicht so effektiv sind, wie ich es mir wünschen würde.\n\nSie sind aber dennoch nützlich genug, um die meiste unerwünschte Aufmerksamkeit zu zügeln.\n\nDa Ihr freundlicherweise Assassinen hergelotst habt, kann ich die Fallen nicht selbst wieder aktivieren.\n\nAlso müsst Ihr das für mich tun. Ich bleibe hier und bewache meine wertvolle Forschung. Verwendet diesen sensorischen Synchronisierer, den ich in der Nähe platziert habe, um herauszufinden, welche Fallen erneut aktiviert werden müssen.", sourceObjective = "Verwendet den sensorischen Synchronisierer und setzt dann 10 ausgelöste Fallen nahe der Höhle des Verbannten zurück.", completion = "Gut. Das sollte uns für eine Weile vor unerwünschter Aufmerksamkeit schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64227] = { id = 64227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungesehene Agenten", description = "Seit Ihr den Weg von Oribos geöffnet habt, haben einige Kartelle die Gelegenheit genutzt, um mich und meine Arbeit auf ziemlich... tödliche Weise zu verfolgen. Sie wissen, wie wichtig meine Forschung für alles ist.\n\nEs werden sicher noch mehr Assassinen kommen, da Ihr ja schließlich einen Weg direkt zu mir aufgezeigt habt!\n\nIch kann mich nicht selbst um sie alle kümmern. Ihr müsst das in Ordnung bringen und mir helfen, meine Geheimnisse zu schützen.\n\nKümmert Ihr Euch für mich um sie.", sourceObjective = "Tötet Assassinen in der Nähe der Höhle des Verbannten.", completion = "Ihr habt Euch als recht nützlich erwiesen. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[64228] = { id = 64228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt bin ich ansprechbar", description = "Ihr habt mir doch tatsächlich ein Orakel gebracht! Und dazu noch ein intaktes!\n\nIch habe noch nie erlebt, dass diese göttlichen Wesen zu jemand anderem außer den Automas sprechen. Es gibt so viel, was wir von ihr über Zereth Mortis erfahren können.\n\nIhr müsst mir alles erzählen!", sourceObjective = "Sprecht mit Firim über das Orakel.", progress = "Erzählt mir, was passiert ist...", completion = "Erstaunlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[64230] = { id = 64230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chiffren der Ersten", description = "Der Weg liegt noch nicht klar vor uns, aber die ersten Schritte sind bereits getan.\n\nEs scheint, dass das göttliche Konstrukt mehr Gefallen an Euch als an mir gefunden hat.\n\nJetzt, da es Euch erste Einblicke gewährt hat, solltet Ihr herausfinden, was es Euch noch zeigen möchte.\n\nDie Ergebnisse dürften sehr aufschlussreich sein.", sourceObjective = "Untersucht die Chiffrenkonsole.", completion = "Spürt Ihr nicht das neue Wissen, das Euch durchströmt?!\n\nDass womöglich ausgerechnet Ihr die Geheimnisse von Zereth Mortis offenbaren werdet...\n\nIch werde Euch sehr genau beobachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64237] = { id = 64237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurgl und der Bandit", description = "Jetzt haben wir alle außer Gurgl. {name}, wir müssen dieses Haustier zu Breanni zurückbringen.\n\nStringfellowe hat einen Schlupfwinkel entdeckt, wo er den Anführer dieser Haustierwilderer vermutet.\n\nSchnappt ihn Euch!", sourceObjective = "Findet den Anführer der Haustierwilderer und bekämpft ihn.", completion = "Ihr seid wieder da, {name}! Und Ihr habt unsere Vorräte, Haustiere und sogar Gurgl zurückgebracht!\n\nGurgl scheint Euch gar nicht mehr verlassen zu wollen.\n\nEr hat in letzter Zeit so viel durchgemacht, und ich werde dem kleinen Kerl bestimmt nicht das Herz brechen.\n\nKümmert Euch gut um meinen kleinen Freund, {name}.\n\nUnd du pass gut auf meinen großen Freund hier auf, Gurgl.", sourceObjectiveStatus = "unverified-source-field" }
quests[64240] = { id = 64240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug der Kyrianer", description = "Wir sind in eine heftige Schlacht am Eingang zum Archiv der Geheimnisse verwickelt! Unsere Streitkräfte brauchen Unterstützung.\n\nBitte führt die anderen Aufgestiegenen an, um die dortigen Kämpfer zu unterstützen.\n\nDie Kämpfer am Boden können sich um die Aufräumarbeiten kümmern, aber sie benötigen Schilde und Heilung.\n\nViel Glück!", sourceObjective = "Helft den Truppen der Pakte am Archiv der Geheimnisse aus der Luft.", completion = "Man muss nicht immer nur mit Gewalt aus der Luft zuschlagen! Manchmal ist ein wenig zusätzliche Heilung die beste Taktik.\n\nIch danke Euch, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[64255] = { id = 64255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Feiern", progress = "Oh, wie schön, sieht wie Temels Hut aus!", completion = "<Euer Butler grinst über beide Ohren, als er den festlichen Hut nimmt.>" }
quests[64266] = { id = 64266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte vom Archivarskodex", description = "Worte können gar nicht zum Ausdruck bringen, wie sehr mich der Gedanke an Eure Hingabe, Korthias Geschichte aufrechtzuerhalten, mit Wärme erfüllt.\n\nBitte, lasst mich Euch meine Dankbarkeit zeigen.", sourceObjective = "Sprecht mit Archivar Roh-Suir im Reliquiar der Erinnerung in Korthia.", completion = "Worte können gar nicht zum Ausdruck bringen, wie sehr mich der Gedanke an Eure Hingabe, Korthias Geschichte aufrechtzuerhalten, mit Wärme erfüllt.\n\nBitte, lasst mich Euch meine Dankbarkeit zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64267] = { id = 64267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisvolle Geschenke von Ve'nari", description = "Ich bin beeindruckt von Eurer schieren Hartnäckigkeit, weiter am Leben und dennoch nützlich zu bleiben, <Schlundgänger/Schlundgängerin>. Ihr erinnert mich an mich selbst, als ich noch jung und naiv war.\n\nNehmt dies und setzt Eure Arbeit fort... an einem weniger auffälligen Ort.", sourceObjective = "Sprecht mit Ve'nari in Ve'naris Zuflucht im Schlund.", completion = "Ich bin beeindruckt von Eurer schieren Hartnäckigkeit, weiter am Leben und dennoch nützlich zu bleiben, Schlundgänger. Ihr erinnert mich an mich selbst, als ich noch jung und naiv war.\n\nNehmt dies und setzt Eure Arbeit fort... an einem weniger auffälligen Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[64271] = { id = 64271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zivilisiertere Art", sourceObjective = "Trefft Nadjia an der Straße nach Korthia.", completion = "An Eurer Kampfhaltung könnt Ihr noch arbeiten. Aber ich danke Euch, dass Ihr in unserer endlosen Kampagne eine Pause für ein Duell gefunden habt. Wir dürfen selbst in Zeiten großer Konflikte niemals die Dinge vergessen, die uns Freude bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64273] = { id = 64273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmung der Helgebundenen" }
quests[64274] = { id = 64274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[64282] = { id = 64282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voller Überraschungen", description = "Ihr überrascht mich immer wieder, <Schlundgänger/Schlundgängerin>. Eure Anwesenheit hier ist höchst unerwartet!\n\nDa wir beide hier sind, sollten wir wohl zusammenarbeiten.\n\nDer Kerkermeister hat einen Tresor voller wertvoller Dinge irgendwo in diesem Riss. Findet ihn für mich und bringt ihn her, damit wir ihn öffnen können. Dann werden wir den Reichtum zwischen uns aufteilen!", sourceObjective = "Findet Zovaals Tresor.", completion = "Dies ist eine durchaus profitable Partnerschaft. Ich bin sicher, das Kartell Ve wird über unseren Erfolg äußerst unglücklich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[64286] = { id = 64286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon des Vorstoßes des Todes", description = "Und wieder wurde mein Aufruf erhört. Eure Mühen sollen nicht unbemerkt bleiben.\n\nSchauen wir mal, ob wir nicht eine passende Belohnung für Eure Taten finden können.", sourceObjective = "Sprecht mit Herzogin Mynx in der Zuflucht des Hüters in Korthia.", completion = "Ich hoffe, dies war nur die erste von vielen Interaktionen.\n\nBitte nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[64287] = { id = 64287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon des Archivarskodex", description = "Ihr habt große Anstrengungen unternommen, um wiederherzustellen, was mir viel bedeutet, <Schlundgänger/Schlundgängerin>.\n\nKommt zu mir in meine Kammer, wenn Ihr bereit seid. Wir müssen noch eine letzte Sache besprechen.", sourceObjective = "Sprecht mit Archivar Roh-Suir im Reliquiar der Erinnerung in Korthia.", completion = "Der Wert dessen, was in unserem Besitz ist, bleibt bestehen, solange es in unserer Gegenwart verbleibt, doch Wissen und Erinnerung existieren an einem Ort, der weder verlegt noch ausgeraubt werden kann. Nur das Vergessen stellt eine Gefahr dar.\nMögen Eure Reise und die Erinnerung an unsere gemeinsame Zeit Euch immer begleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64288] = { id = 64288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon von Ve'nari", description = "Kommt, <Schlundgänger/Schlundgängerin>. Trefft mich an meiner Zuflucht.\n\nWir müssen noch eine letzte Sache bereden.\n\n...und passt auf, dass Euch niemand folgt.", sourceObjective = "Sprecht mit Ve'nari in Ve'naris Zuflucht im Schlund.", sourceObjectiveStatus = "unverified-source-field" }
quests[64289] = { id = 64289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So viele Kleinteile", description = "So viel ging verloren, als Korthia in den Schlund gezogen wurde.\n\nUnbezahlbare Relikte wurden einfach in Stücke gerissen. Ich habe einige Kreaturen gesehen, die mit den Überresten dieser Objekte herumliefen.\n\nWir müssen sie zurückholen.\n\nStellt Euch den Streitkräften des Kerkermeisters und durchsucht die Überreste Korthias nach allem, was von unserem einst so glorreichen Archiv noch übrig ist.", sourceObjective = "Bergt 50 Reliktfragmente von seltenen Kreaturen und aus Schätzen in ganz Korthia.", completion = "Damit wird es gehen. Es gibt so viel, was ich tun kann, um sie zu restaurieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[64290] = { id = 64290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschung sammeln", description = "Ihr habt gute Arbeit geleistet. All diese Fragmente werden uns sehr dabei helfen, unser Archiv wiederaufzubauen.\n\nMit dem, was Ihr gefunden habt, kann ich noch weitere Forschungsdaten zu dem entschlüsseln, was in Korthia verloren ging.\n\nDanach ist es an Euch, innerhalb Korthias noch weitere Fragmente und Relikte für unser Archiv zu suchen.", sourceObjective = "Sprecht mit Archivar Roh-Suir, um korthianische Relikte für die katalogisierte Forschung bei ihm abzugeben.", completion = "Das sollte genügen. Mit etwas mehr Forschung wird das Reliquiar bald wieder erblühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64292] = { id = 64292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maelie die Wanderin", description = "Ich kann Euch gar nicht genug danken, dass Ihr Maelie gefunden habt! Ich glaube, sie ist einfach ein bisschen zu viel für mich, wisst Ihr?\n\nWürdet Ihr vielleicht auf sie aufpassen? Sie scheint Euch wirklich zu mögen!", sourceObjective = "Nehmt die Verantwortung für Maelie an.", completion = "Passt gut auf Maelie auf, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[64304] = { id = 64304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Möglichkeiten warten", description = "Habt Ihr es eilig? Ah, ja. <Schlundgänger/Schlundgängerin>, Ihr seid nicht zufällig dabei, die neue geheimnisvolle Landmasse innerhalb des Schlunds zu erkunden, oder?\n\nIch frage mich, was für Geheimnisse dort verborgen liegen.\n\nVielleicht können wir einander irgendwie behilflich sein.\n\nWenn Ihr interessiert seid, sollten wir unser Gespräch fortsetzen. Ansonsten zieht nur weiter. Ich finde schon jemand anderen, der mir weiterhilft.", sourceObjective = "Besiegt 20 Spielercharaktere in Korthia.", completion = "Wirklich ausgezeichnete Arbeit.\n\nEine Belohnung für Eure Mühen. Auf unsere weiterhin gemeinsamen Interessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64306] = { id = 64306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedingung zum Questabschluss" }
quests[64314] = { id = 64314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneuerte Pakte", description = "Wir haben uns darauf konzentriert, dass der Kerkermeister nicht die Barriere um den Schlund durchbrechen und in die restlichen Schattenlande einfallen kann.\n\nStattdessen hat er den Schlund selbst erweitert, um Oribos zu verschlingen und das Siegel der Richterin an sich zu reißen.\n\nIch verstehe noch immer nicht ganz, was wir an der Spitze von Torghast gesehen haben. Aber der Primus tut das ganz sicher.\n\nEs wird Zeit für seinen Notfallplan. Die Pakte werden in Kürze mit ihren Siegeln eintreffen.\n\nInformiert den Primus, dass wir bereit sind.", sourceObjective = "Sprecht mit dem Primus und holt Euch dann die Siegel von den Pakten.", completion = "Ausgezeichnet, Sterblicher. Ihr habt Euren Teil erfüllt.\n\nNun beginnt meine Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[64322] = { id = 64322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran der Nachtfae", description = "Der Ardenwald ist so sicher wie schon seit Langem nicht mehr, dank Euch.\n\nEure Leistungen sind nicht unbemerkt geblieben, selbst über die Grenzen des Ardenwalds hinaus.\n\nDie Erzählungen über Eure Siege klingen in den Hallen von Oribos wider. Zo'Sorg, der Meister des Konflikts, wünscht, Euch in der Enklave zu treffen.\n\nEr ist außerordentlich interessiert an der Kunst des Krieges. Ich empfehle, dass Ihr ihn nicht warten lasst.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Ah, {name}. Ich habe viele Geschichten über Eure Heldentaten auf dem Schlachtfeld gehört.\n\nEs ist mir wichtig, große Kämpfer wie Euch gut auszurüsten. Zo'dash hat meine Genehmigung, Eure Rüstungen und Waffen weiter aufzuwerten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64323] = { id = 64323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran der Kyrianer", description = "Die Bastion heilt dank Euch, {name}. Der Weg ist frei.\n\nEure Leistungen sind nicht unbemerkt geblieben, selbst über die Grenzen der Bastion hinaus.\n\nDie Erzählungen über Eure Siege klingen in den Hallen Oribos' wider. Zo'Sorg, der Meister des Konflikts, wünscht Euch in der Enklave zu treffen.\n\nEr ist außerordentlich interessiert an der Kunst des Krieges. Ich empfehle, dass Ihr ihn nicht warten lasst.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Ah, {name}. Ich habe viele Geschichten über Eure Heldentaten auf dem Schlachtfeld gehört.\n\nEs ist mir wichtig, große Kämpfer wie Euch gut auszurüsten. Zo'dash hat meine Genehmigung, Eure Rüstungen und Waffen weiter aufzuwerten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64324] = { id = 64324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran der Nekrolords", description = "Der Einfluss der Nekrolords wächst dank Euch, {name}!\n\nEure Leistungen sind nicht unbemerkt geblieben, selbst über die Grenzen Maldraxxus' hinaus.\n\nDie Erzählungen über Eure Siege klingen in den Hallen Oribos' wider. Zo'Sorg, der Meister des Konflikts, wünscht Euch in der Enklave zu treffen.\n\nEr ist außerordentlich interessiert an der Kunst des Krieges. Ich empfehle, dass Ihr ihn nicht warten lasst.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Ah, {name}. Ich habe viele Geschichten über Eure Heldentaten auf dem Schlachtfeld gehört.\n\nEs ist mir wichtig, große Kämpfer wie Euch gut auszurüsten. Zo'dash hat meine Genehmigung, Eure Rüstungen und Waffen weiter aufzuwerten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64325] = { id = 64325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran von Sündensturz", description = "Der Einfluss von Sündensturz wächst dank Eurer Siege, {name}!\n\nEure Leistungen sind nicht unbemerkt geblieben, selbst über die Grenzen Revendreths hinaus.\n\nDie Erzählungen über Eure Siege klingen in den Hallen Oribos' wider. Zo'Sorg, der Meister des Konflikts, wünscht Euch in der Enklave zu treffen.\n\nEr ist außerordentlich interessiert an der Kunst des Krieges. Ich empfehle, dass Ihr ihn nicht warten lasst.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Ah, {name}. Ich habe viele Geschichten über Eure Heldentaten auf dem Schlachtfeld gehört.\n\nEs ist mir wichtig, große Kämpfer wie Euch gut auszurüsten. Zo'dash hat meine Genehmigung, Eure Rüstungen und Waffen weiter aufzuwerten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64340] = { id = 64340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezaubernd", progress = "Tragen eigentlich alle auf Eurer Welt diese spitzen Hüte?!", completion = "<Euer Butler lässt ein furchtbar unbeholfenes Gackern hören, als er den Hut nimmt, dann hustet er und erinnert sich an die Etikette.>" }
quests[64368] = { id = 64368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikteffizienz", sourceObjective = "Eure Arbeit zur Wiederherstellung des Reliquiars war von unschätzbarem Wert.\n\nIch habe neue Methoden zum Aufspüren von Relikten entdeckt. Ich hoffe, sie werden Euch helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64376] = { id = 64376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Quest" }
quests[64430] = { id = 64430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus dem Tee kommen", description = "Anscheinend sind Tubbins und Gubbins irgendwohin verschwunden.\n\nIch mache mir wirklich Sorgen um die zwei. Seid doch so lieb und seht nach ihnen. Man kann nie wissen, welcher Unfug ihnen jetzt schon wieder einfällt.\n\nAls ich sie das letzte Mal gesehen habe, haben sie mit einer der Feen aus dem Ardenwald gesprochen. Es ging um die Feinheiten des Teekochens.", sourceObjective = "Findet Tubbins und Gubbins.", completion = "Ah, da seid Ihr ja alle wieder und auch noch unverletzt. Wunderbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[64432] = { id = 64432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus Stärke wird Schwäche", sourceObjective = "Ladet den Blitzableiter auf und tötet dann Schlundgebundene.", completion = "Ich sagte doch, es würde Euch nicht schaden. Wie ist der Test gelaufen? Ich hätte zu gern ihre Gesichter gesehen, als sie bemerkt haben, dass ihre schicke Rüstung plötzlich der Grund dafür war, dass sie vernichtet wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[64437] = { id = 64437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informiert den Primus", description = "{name}, kehrt nach Korthia zurück und sagt dem Primus, dass das Siegel der Winterkönigin wiederhergestellt werden konnte.", sourceObjective = "Kehrt zum Primus in Korthia zurück.", completion = "Ah, gut. Wenn das Siegel der Königin jetzt wiederhergestellt ist, sind wir unserem Vorhaben, Zovaal aufzuhalten, einen entscheidenden Schritt näher gekommen. Vielen Dank für diese Information.", sourceObjectiveStatus = "unverified-source-field" }
quests[64438] = { id = 64438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrüstung aufbessern", description = "Die Forschungsarbeiten, die Ihr findet, können viele Möglichkeiten erschließen.\n\nEine Möglichkeit ist die Verbesserung von Ausrüstung, die Ihr in Korthia finden könnt.\n\nSprecht mit meinem Assistenten in der Nähe. Er kann unsere Forschung nutzen, um die Leistungsfähigkeit dieser Ausrüstung wiederherzustellen.", sourceObjective = "Sprecht mit Gelehrtenassistent Kah-Vez, um ein Stück Ausrüstung aus Korthia aufzuwerten.", progress = "Ich werde tun, was ich kann, um Euch zu helfen, Schlundgänger.", completion = "Das ist doch das Mindeste, was wir tun können, um Euch bei Eurer Aufgabe zu helfen, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[64441] = { id = 64441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein loser Faden", description = "<Ein Buch scheint vor Kurzem im nahe gelegenen Venthyrlager vom Tisch gestoßen worden zu sein.\n\nDie Venthyr wären wahrscheinlich dankbar, wenn Ihr es ihnen zurückgebt, bevor einer der Gromits es als Nistmaterial benutzt.>", sourceObjective = "Hebt das Buch auf, um es zurückzugeben.", completion = "<Es scheint, als hättet Ihr und Mal'Ganis noch eine Rechnung offen. Ihr seid Euch sicher: Wenn Ihr Euch irgendwann dem Kerkermeister stellt, wird auch der Schreckenslord dort sein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[64458] = { id = 64458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurerin: Sulanoom", sourceObjective = "Eure Hingabe an den Ardenwald steht außer Frage, {name}.\n\nBesonders Euer unerschütterlicher Geist hat Sulanoom sehr beeindruckt. So sehr, dass sie uns bei unserem Kampf hier unterstützen möchte.\n\nDann wollen wir ihre Hilfe mal nicht verschwenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[64459] = { id = 64459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurerin: Elwyn", sourceObjective = "Der Wald segnet uns, {name}. Eure Bemühungen um das Wohlergehen des Ardenwalds haben Aufmerksamkeit erregt.\n\nDie ehrenwerte Elwyn hat sich unserem Kampf angeschlossen.\n\nGemeinsam werden wir das Reich beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64460] = { id = 64460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurerin: Yanlar", sourceObjective = "{name}, ihr habt Euch in unzähligen Schlachten für den Ardenwald tapfer geschlagen.\n\nYanlar hat sich Euch in vielen Kämpfen in den ganzen Schattenlanden angeschlossen und war stets von Eurem Mut beeindruckt.\n\nEs freut mich, dass sie nun permanent an Eurer Seite kämpfen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[64461] = { id = 64461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Hermestes", sourceObjective = "Euer Vertrauen in die Bastion ist eine Inspiration, {name}.\n\nHermestes hat selbst gesehen, mit welchem Eifer Ihr für unsere Sache streitet.\n\nDas war auch der Grund für seine Entscheidung, sich uns hier in der Festung anzuschließen, um nun mit neuen Aufgaben dem Wohl der gesamten Schattenlande zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64462] = { id = 64462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Cromas der Mystiker", sourceObjective = "Seid gegrüßt, mein sterblicher Freund! Ich habe gute Nachrichten.\n\nCromas der Mystiker verfolgt seit einiger Zeit mit großem Interesse Euren Fortschritt bei den Kyrianern.\n\nNun möchte er sich Euch anschließen und mit all seiner Kraft für Eure Sache streiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64463] = { id = 64463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurerin: Aurische Geistführerin", sourceObjective = "Es scheint, als hätten wir noch eine Rekrutin, {name}.\n\nIch fühle mich geehrt, Euch mitzuteilen, dass die aurische Geistführerin uns mit all ihrer Weisheit und ihrem Geschick von nun an unterstützen wird.\n\nWas für eine wunderbare Verbündete!", sourceObjectiveStatus = "unverified-source-field" }
quests[64464] = { id = 64464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurerin: Lyra Hagelsturm", sourceObjective = "Heute gab es eine spannende Entwicklung, {name}!\n\nLyra Hagelsturm möchte uns hier am Sitz beitreten! Ihre Expertise wird uns eine wahre Bereicherung sein.\n\nGeht nun und kämpft gemeinsam für Maldraxxus!", sourceObjectiveStatus = "unverified-source-field" }
quests[64465] = { id = 64465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Enceladus", sourceObjective = "Euer Engagement ist inspirierend, {name}.\n\nIhr habt Enceladus wahrlich beeindruckt. Bei der Reparatur Eurer Waffen hat er gesehen, dass Ihr ein wahrer Krieger seid!\n\nDas Ziel ist klar, kämpft für Maldraxxus!", sourceObjectiveStatus = "unverified-source-field" }
quests[64466] = { id = 64466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Todesreißer", sourceObjective = "Heute haben wir aufregende Neuigkeiten erhalten, {name}.\n\nBaronin Draka ließ uns die besondere Ehre zukommen, Todesreißer in unsere Dienste zu stellen.\n\nMit der Hilfe solch eines wilden Tiers wird Maldraxxus siegreich sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[64467] = { id = 64467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurer: Chachi der Künstler", sourceObjective = "Ausgezeichnete Neuigkeiten, {name}.\n\nChachi der Künstler möchte seinen exquisiten Geschmack im Dienste von Revendreth einsetzen.\n\nSetzt seine Fähigkeiten weise ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[64468] = { id = 64468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurerin: Madame Iza", sourceObjective = "Madame Iza hat sich entschlossen, sich im Dienste für Revendreth ins Gefecht zu stürzen.\n\nIst das nicht aufregend, {name}?\n\nNicht nur ihre Anmerkungen schneiden tief, also unterschätzt sie nicht im Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[64469] = { id = 64469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurerin: Lucia", sourceObjective = "Lucia möchte unserer Sache mit ihrem Reichtum an Können dienen, {name}.\n\nSie kann es kaum erwarten, jene zu bestrafen, die sich gegen Revendreth stellen.\n\nSetzt sie sinnvoll ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[64506] = { id = 64506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Suche", description = "Der Kodex enthält sehr detaillierte Aufzeichnungen. Über Gegenstände, die für immer verloren sind... und einige, die bis heute überdauert haben.\n\nEinige dieser mächtigen Relikte sind vielleicht noch irgendwo in Korthia versteckt.\n\nSeht Euch im Reliquiar um. Dort findet Ihr Echos einiger Artefakte, die in Korthia noch intakt anzutreffen sind.\n\nPrägt sie Euch genau ein. Ihr müsst sie finden und zu mir zurückbringen.", sourceObjective = "Findet im Reliquiar der Erinnerung heraus, welche Relikte fehlen.", completion = "Das sind nur einige der fehlenden Relikte.\n\nIhr habt die Macht, sie zurückzuholen, wo auch immer sie in Korthia versteckt sein mögen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64509] = { id = 64509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stilvolle Kopfbedeckung", progress = "Ist das so ein Kopfdeckel, wie Kuhl von den Sündensteinschwofern ihn trägt?", completion = "Ist das wirklich sein Ersatzhut? Ich kann es nicht fassen. Ich glaube, da ist sogar noch Schweiß am Band... Vielen Dank!" }
quests[64511] = { id = 64511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlende Relikte", description = "Dank Eurer Hilfe konnte ich noch weitere Forschungsdaten zu den verlorenen Relikten aus dem Archiv wiederherstellen.\n\nIch habe mich eingehend mit dem Kodex befasst und glaube, dass es in Korthia noch mehr Relikte gibt, die wir bergen könnten.\n\nSie waren in Truhen versiegelt, und diese Truhen wurden im Zuge des ersten Angriffs überall in Korthia verstreut.\n\nHier drin habe ich alle fehlenden Relikte zusammengestellt. Prägt sie Euch gut ein. Wir müssen sie finden.", sourceObjective = "Untersucht die fehlenden Relikte im Reliquiar der Erinnerung.", progress = "Habt Ihr die fehlenden Relikte gesehen?", completion = "Bitte tut, was Ihr könnt, um diese Relikte zu finden. Wir dürfen nicht zulassen, dass all dieses Wissen für immer verloren geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[64513] = { id = 64513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ve'rayns Kopf", description = "<Ve'rayn macht schon seit einiger Zeit Jagd auf Ve'nari. Ve'nari wäre sehr an einem Beweis interessiert, dass dieses Problem endgültig aus dem Weg geschafft wurde.>", sourceObjective = "Liefert Ve'rayns Kopf bei Ve'nari in Ve'naris Zuflucht ab.\n\nBereitgestellter Gegenstand:", completion = "Ist das etwa das, was ich vermute...?", sourceObjectiveStatus = "unverified-source-field" }
quests[64517] = { id = 64517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Byron Test - Item Gained" }
quests[64518] = { id = 64518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Byron Test - Obtain Any Item" }
quests[64519] = { id = 64519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Archive", description = "Ich habe meine Forschungen zu einigen weiteren Relikten abgeschlossen, die womöglich noch immer in Korthia existieren. Ich glaube, sie befinden sich in unseren kleineren Archiven.\n\nMit Eurer Hilfe kann ich Geräte herstellen, die den Zugang zu diesen Archiven wiederherstellen.\n\nSeht Euch die Echos der Relikte an, die noch fehlen. Merkt sie Euch gut, damit Ihr genau wisst, wonach Ihr suchen müsst.", sourceObjective = "Untersucht die fehlenden Relikte im Reliquiar der Erinnerung.", completion = "Vielen Dank für all Eure Hilfe. Eurem Fleiß ist es zu verdanken, dass unser Reliquiar bald in neuer Pracht erstrahlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[64521] = { id = 64521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtpläne der Helgebundenen", description = "<Diese Schlachtpläne enthalten Szenarien für Angriffe auf Korthia sowie detaillierte Berichte über die Verteidigungskapazitäten, die der Vorstoß des Todes in dieser Region aufbringen kann.\n\nHerzogin Mynx in der Zuflucht des Hüters könnte diese Informationen schnell allen zukommen lassen, die sie benötigen.>", sourceObjective = "Liefert die Schlachtpläne der Helgebundenen bei Herzogin Mynx in der Zuflucht des Hüters ab.\n\nBereitgestellter Gegenstand:", completion = "<Die Augen von Herzogin Mynx werden immer größer, während sie durch die Dokumente blättert, die Ihr mitgebracht habt.>\n\nIch werde die hier sofort verteilen. Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[64522] = { id = 64522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene korthianische Vorräte", description = "<Diese Vorräte wurden unbemerkt aus dem Riss gestohlen. Allesamt sind sie mit dem Siegel des Vorstoßes des Todes versehen.\n\nHerzogin Mynx in der Zuflucht des Hüters wäre sehr dankbar, wenn sie jemand zurückbringen würde.>", sourceObjective = "Liefert die gestohlenen korthianischen Vorräte bei Herzogin Mynx in der Zuflucht des Hüters ab.\n\nBereitgestellter Gegenstand:", completion = "<Herzogin Mynx sieht Euch fassungslos an.>\n\nWO habt Ihr die gefunden?!\n\nTja, wie soll ich denn Diebe aufhalten, die ich nicht mal sehen kann? Feiges Schattenpack!", sourceObjectiveStatus = "unverified-source-field" }
quests[64526] = { id = 64526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisvolle Risse", description = "Vielen Dank für Eure Hilfe, {name}. Ich habe im Kodex noch mehr Relikte gefunden, die nach wie vor unbeschädigt sind.\n\nDer Schlüssel zu diesen Relikten liegt in den seltsamen Rissen in ganz Korthia.\n\nIch kann Euch jetzt eine Möglichkeit schaffen, diese Risse zu betreten, damit Ihr noch weitere unserer fehlenden Relikte bergen könnt.\n\nWie zuvor solltet Ihr Euch die Echos ansehen, damit Ihr wisst, wonach Ihr suchen sollt. Prägt sie Euch bitte gut ein, bevor Ihr aufbrecht.", sourceObjective = "Untersucht die fehlenden Relikte im Reliquiar der Erinnerung und kauft einen reparierten Rissschlüssel von Roh-Suir.", completion = "Vielen Dank für all Eure Hilfe. Eurem Fleiß ist es zu verdanken, dass unser Reliquiar bald in neuer Pracht erstrahlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[64527] = { id = 64527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtung der Jagd", description = "Bei unseren Beobachtungen der Konflikte Eurer Art ist uns eine hohe Rate an entkommener Jagdbeute aufgefallen.\n\nDies ist unseren Bemühungen um eine genaue Beobachtung eher abträglich.\n\nDer Beobachter hat ein Werkzeug beschafft, von dem wir glauben, dass es Eure Fähigkeit zur Forcierung von Konflikten steigern sollte.\n\nBevor ich es Euch gebe, bitten wir Euch, zunächst Eure Bereitschaft zur Teilnahme an solchen Konflikten unter Beweis zu stellen. Nur so können wir sicher sein, dass sich diese Investition für uns auch gebührend auszahlt.", sourceObjective = "Aktiviert den Kriegsmodus und tötet 1 |4Spielercharakter:Spielercharaktere; in der Welt.", completion = "Ausgezeichnet. Wir werden Eure zukünftigen Bemühungen mit großem Interesse verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64528] = { id = 64528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlingsattel", description = "<Als Ihr Euch vom Rücken des entkommenen Wildlings gleiten lassen habt, hat dieser den Sattel zu Euren Füßen abgeschüttelt. Nur widerwillig ist er von Eurer Seite gewichen und den Nachtfae gefolgt, die ihn zur Zuflucht des Hüters zurückgebracht haben.\n\nReldorn in der Zuflucht des Hüters weiß vielleicht, was diese Geste bedeutet.>", sourceObjective = "Bringt den Wildlingsattel zu Reldorn in der Zuflucht des Hüters.\n\nBereitgestellter Gegenstand:", completion = "<Reldorn lacht, als er Euch mit dem Sattel sieht.>\n\nIch hatte mich schon gefragt, wo der Sattel dieses Wildlings geblieben ist. Er hat bis jetzt jeden Reiter abgelehnt, der ihn als Begleiter wollte. Es scheint, als hätte er endlich jemanden gefunden, den er für würdig hält.\n\nIhr habt heute einen wirklich sturen und treuen Gefährten gewonnen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64529] = { id = 64529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intakter Aquilonkern", description = "<Der riesige Verschlinger, der bei seinem Tod diesen Energiekern fest umklammert hielt, hat ihn zweifellos aus einem der zerstörten Aquilons in seiner Umgebung gerissen. Der Energiekern selbst scheint fast vollständig intakt zu sein.\n\nDeos in der Zuflucht des Hüters kann Euch helfen, einen Aquilon zu finden, den Ihr damit antreiben könnt.>", sourceObjective = "Bringt den intakten Aquilonkern zu Deos in der Zuflucht des Hüters.\n\nBereitgestellter Gegenstand:", completion = "<Deos' Augen leuchten auf, als er den intakten Energiekern in Eurer Hand sieht.>\n\nDer Archon sei Dank! Ich konnte einige beschädigte Aquilons aus dem Kampf vorhin retten, und einem fehlt ein Energiekern. Ich werde ihn sofort reparieren, dann könnt Ihr ihn mit Euch nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64530] = { id = 64530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabschwingenkristall", description = "<Dieses große Kristallfragment ist von dem riesigen Körper des Konstrukts abgesplittert. Aus seinem Innern dringt das Knistern von Energieblitzen.\n\nDie Steinhauerin in der Zuflucht des Hüters könnte mit diesem Kristall eine Grabschwinge für Euch ermächtigen.>", sourceObjective = "Bringt den Grabschwingenkristall zur Steinhauerin in der Zuflucht des Hüters.\n\nBereitgestellter Gegenstand:", completion = "<Die Steinhauerin zieht eine Augenbraue hoch, als Ihr den mächtigen Kristall in ihre Hand legt.>\n\nDieser Kristall ist wirklich einzigartig... Zum Glück weiß ich genau, welches Steinkind diesen Schatz auch verdient hat. Ich bin sicher, Ihr werdet Euch gut um sie kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[64531] = { id = 64531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'geth" }
quests[64532] = { id = 64532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzten Relikte", description = "Ich habe großartige Neuigkeiten, {name}. Ich weiß nun, wo die letzten fehlenden Relikte sind!\n\nEs könnte etwas schwierig für Euch werden, sie auch zu finden, aber ich habe genau die richtige Forschung, um Euch zu helfen.\n\nSchaut Euch bitte die letzten fehlenden Relikte an. Wir haben es fast geschafft!", sourceObjective = "Untersucht die fehlenden Relikte im Reliquiar der Erinnerung und kauft den Untersuchungsbericht: Uralte Schreine.", progress = "Habt Ihr die fehlenden Relikte gesehen?", completion = "Vielen Dank für all Eure Hilfe. Eurem Fleiß ist es zu verdanken, dass unser Reliquiar bald in neuer Pracht erstrahlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[64541] = { id = 64541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis des Todes", progress = "Wollt Ihr etwas tauschen, Schlundgänger?", completion = "Bei all den neuen Eindringlingen im Schlund muss ich meinen Nachschub an Stygia sichern. Eure Bemühungen, mich weiter mit Nachschub zu versorgen, werden nicht unbemerkt bleiben, und Ihr wisst ja stets, wo Ihr mich findet." }
quests[64546] = { id = 64546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen von Graf Denathrius", sourceObjective = "Es scheint, als wäre ich ganz und gar Eurer Gnade ausgeliefert, {name}.\n\nAls Theotars Schöpfung ist es meine Pflicht, Eurem Hof beizuwohnen, wann immer Ihr es wünscht.\n\nIch nehme an, wir werden uns bald wiedersehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[64549] = { id = 64549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legende der Animaquelle", description = "<Das hier scheint ein unvollständiger Satz Notizen eines Archivars zu sein, der irgendwo tief in Korthia nach einer mythischen Animaquelle gesucht hat.\n\nBehüterin Vesperblüte im Herz des Waldes könnte Euch helfen, ein Team für die Suche nach dieser Quelle zusammenzustellen.>", sourceObjective = "Bringt die Legende der Animaquelle zu Behüterin Vesperblüte im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "<Behüterin Vesperblüte studiert aufmerksam die Dokumente, die Ihr mitgebracht habt.>\n\nDie Dokumentation ist unvollständig. Es ist unklar, ob der Archivar überhaupt überlebt hat...\n\nAber die Geschichten über die Anima sind unglaublich und hier finden sich genug Details, um eine Expedition zu entsenden.\n\nDas wird nicht leicht. Der Archivar warnt vor vielen Gefahren, die diese Animaquelle beschützen...", sourceObjectiveStatus = "unverified-source-field" }
quests[64551] = { id = 64551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legende der Animaquelle", description = "<Das hier scheint ein unvollständiger Satz Notizen eines Archivars zu sein, der irgendwo tief in Korthia nach einer mythischen Animaquelle gesucht hat.\n\nMerick Feldnarb im Sitz des Primus könnte Euch helfen, ein Team für die Suche nach dieser Quelle zusammenzustellen.>", sourceObjective = "Bringt die Legende der Animaquelle zu Merick Feldnarb im Sitz des Primus.\n\nBereitgestellter Gegenstand:", completion = "<Merick Feldnarb studiert aufmerksam die Dokumente, die Ihr mitgebracht habt.>\n\nDie Dokumentation ist unvollständig. Es ist unklar, ob der Archivar überhaupt überlebt hat...\n\nAber die Geschichten über die Anima sind wirklich beeindruckend und hier finden sich genug Details, um eine Expedition zu entsenden.\n\nDas wird nicht leicht. Der Archivar warnt vor vielen Gefahren, die diese Animaquelle beschützen...", sourceObjectiveStatus = "unverified-source-field" }
quests[64552] = { id = 64552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legende der Animaquelle", description = "<Das hier scheint ein unvollständiger Satz Notizen eines Archivars zu sein, der irgendwo tief in Korthia nach einer mythischen Animaquelle gesucht hat.\n\nKoros in der Elysischen Feste könnte Euch helfen, ein Team für die Suche nach dieser Quelle zusammenzustellen.>", sourceObjective = "Bringt die Legende der Animaquelle zu Koros in der Elysischen Feste.\n\nBereitgestellter Gegenstand:", completion = "<Koros studiert aufmerksam die Dokumente, die Ihr mitgebracht habt.>\n\nDie Dokumentation ist unvollständig. Es ist unklar, ob der Archivar überhaupt überlebt hat...\n\nAber die Geschichten über die Anima sind schlüssig und hier finden sich genug Details, um eine Expedition zu entsenden.\n\nDas wird nicht leicht. Der Archivar warnt vor vielen Gefahren, die diese Animaquelle beschützen...", sourceObjectiveStatus = "unverified-source-field" }
quests[64553] = { id = 64553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legende der Animaquelle", description = "<Das hier scheint ein unvollständiger Satz Notizen eines Archivars zu sein, der irgendwo tief in Korthia nach einer mythischen Animaquelle gesucht hat.\n\nTaktikerin Sakaa in Sündensturz könnte Euch helfen, ein Team für die Suche nach dieser Quelle zusammenzustellen.>", sourceObjective = "Bringt die Legende der Animaquelle zu Taktikerin Sakaa in Sündensturz.\n\nBereitgestellter Gegenstand:", completion = "<Taktikerin Sakaa studiert aufmerksam die Dokumente, die Ihr mitgebracht habt.>\n\nDie Dokumentation ist unvollständig. Es ist unklar, ob der Archivar überhaupt überlebt hat...\n\nAber die Geschichten über die Anima sind unglaublich und hier finden sich genug Details, um eine Expedition zu entsenden.\n\nDas wird nicht leicht. Der Archivar warnt vor vielen Gefahren, die diese Animaquelle beschützen...", sourceObjectiveStatus = "unverified-source-field" }
quests[64554] = { id = 64554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venthyrangriff", description = "Unser Angriff hat die Truppen des Kerkermeisters überrumpelt. Wir werden die Verdammnisfestung überrennen und seine Champions am Altar der Herrschaft besiegen!\n\nWir brauchen Euch, <Schlundgänger/Schlundgängerin>. Unterstützt unsere Soldaten auf dem Schlachtfeld!", sourceObjective = "Schließt 1 Quests in der Verdammnisfestung und im Antlitz des Vergessens ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[64555] = { id = 64555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnis und Erkenntnis", description = "Jeder Pakt hat seine eigenen Spezialisten mitgebracht, allesamt Koryphäen auf ihrem jeweiligen Gebiet. Einige von ihnen haben sich aufgemacht, um dieses unbekannte Land zu erkunden.\n\nSprecht mit ihnen. Sie alle sollten einen Bericht zu ihren Erkenntnissen verfasst haben. Bringt sie zu mir.", sourceObjective = "Sprecht mit den Spähern in Korthia.", progress = "Habt Ihr alle Späher gefunden?", completion = "Die meisten dieser Informationen sind sehr hilfreich. Ich danke Euch, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[64556] = { id = 64556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde in der Not", description = "Die Bewohner von Korthia haben viel durchgemacht. Ohne uns hätten die Streitkräfte des Kerkermeisters wohl auch den Rest der Stadt der Geheimnisse in Trümmer gelegt.\n\nWenn wir hier etwas erreichen wollen, müssen wir den Bedürftigen helfen.\n\nSteht unseren Verbündeten zur Seite, <Schlundgänger/Schlundgängerin>. Seht Euch überall genau um und lasst keinen Verbündeten des Kerkermeisters lebendig entkommen.", sourceObjective = "Schließt in ganz Korthia 3 tägliche Quests von Mikanikos, Ta'nasi und Kael'thas ab.", completion = "Das bringt uns einen Schritt näher an unser Ziel. Zovaals Herrschaft über dieses verfluchte Land muss endlich enden.", sourceObjectiveStatus = "unverified-source-field" }
quests[64557] = { id = 64557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Dunkelheit gefunden", description = "Das Kartell Ve hat den Ruf, sich an gefährlichen Orten herumzutreiben, um nach Schätzen zu suchen. Mit ein wenig Vernunft würde es begreifen, dass man die Beschaffung und den Verkauf solcher Waren den Xy überlässt. Nun gut.\n\nEines seiner Mitglieder ist mit einer geplünderte Kiste voller mächtiger Gegenstände nach Torghast verschwunden. Er hat wohl gedacht, damit seine Erkundung absichern zu können. Was für ein Irrsinn!", sourceObjective = "Findet Ve'nish in Torghast, Turm der Verdammten.", completion = "Halt, keinen Schritt näher! Gebt Euch zu erkennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64560] = { id = 64560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animarücknahme", description = "Für unseren Einsatz hier brauchen wir konstanten Nachschub an Truppen, Vorräten und Anima. Letztere zu besorgen, gestaltet sich augenscheinlich am schwierigsten, aber ich habe einen gewissen Einfallsreichtum entwickelt.\n\nIn der Nähe gibt es eine üppige Quelle an Anima: die Verschlinger, die gerade das Refugium der Weisung überrennen. Das ist nicht so leicht, wie sie einer Seele zu entreißen, aber genauso effektiv. Zumindest wenn man stark genug ist. Seid Ihr das?", sourceObjective = "Gewinnt 8 verschlungene Anima von den Verschlingern im Refugium der Weisung zurück.", progress = "Jeder Tropfen Anima, den wir zurückgewinnen können, ist eine potenzielle Waffe gegen den Kerkermeister.", completion = "Ihr könnt mir diese Anima anvertrauen. Ich werde dafür sorgen, dass sie gegen den Kerkermeister und seine Truppen eingesetzt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[64561] = { id = 64561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtungsdaten", description = "Ich grüße Euch, <Schlundgänger/Schlundgängerin>. Habt Ihr einen Moment Zeit?\n\nWie Ihr sicher wisst, hat mein Kartell insgeheim Beobachtungsgeräte über ganz Korthia verteilt. Aber diese Daten nützen uns nichts, wenn sie nicht abgerufen werden. Und genau da kommt Ihr ins Spiel.\n\nDie Aufzeichnungen am Windgepeitschten Nistgipfel und am Ästuarium des Erwachens sollten zur Abholung bereit sein. Die Geräte selbst werdet Ihr nicht sehen können, aber die Daten erscheinen Euch als hell leuchtende Kugel.\n\nUnd vergesst nicht, auch unter der Erde nachzusehen!\n\nWenn Ihr mir diese Daten bringt, werde ich Euch großzügig belohnen.", sourceObjective = "Sammelt 5 Beobachtungsdaten am Windgepeitschten Nistgipfel und am Ästuarium des Erwachens in Korthia ein.", progress = "Habt Ihr die Beobachtungsdaten vom Windgepeitschten Nistgipfel und dem Ästuarium des Erwachens beschafft?", completion = "Orte wie der Nistgipfel und das Ästuarium waren gewiss schon vor all dieser Zerstörung ausgesprochen trostlos. Was für interessante Kreaturen sich dort versammeln.\n\nOb sie wohl alle diese Veränderungen überleben? Oder werden sich einige anpassen und sogar noch gefährlicher werden?\n\nHier ist Eure Belohnung, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64562] = { id = 64562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiler gesucht", description = "Es gibt zu viele Verwundete auf dem Schlachtfeld!\n\nNicht jeder lässt sich durch Draufklopfen wieder hinbiegen. Wir brauchen mehr Heiler.\n\nNehmt mein Gerät und sorgt dafür, dass die Verwundeten wieder auf die Beine kommen!", sourceObjective = "Heilt 10 verwundete Paktverbündete im Quorum des Suchers.", completion = "Das hat ihnen wieder auf die Beine geholfen!\n\nAuch die kleinste Hilfe unterstützt uns im Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[64567] = { id = 64567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Gelehrte", description = "Ah, <Schlundgänger/Schlundgängerin>. Eure Rückkehr bringt uns Grund zur Hoffnung und die so dringend erforderliche Hilfe.\n\nNach wie vor werden einige Gelehrte vermisst. Wir glauben, dass sie zuletzt im großen Hof ihren Studien nachgingen. Es steht zu befürchten, dass wir sie verloren haben oder, was noch schlimmer wäre, dass sie von jenen verschleppt wurden, die unsere Lebensweise stören wollen.\n\nKehrt zu mir zurück, wenn Ihr ein paar Antworten gefunden habt.\n\nMöge der Pfad Euch leiten.", sourceObjective = "Findet den Gelehrten Roh-Suir in Korthia.", completion = "Wie... wie habt Ihr mich gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[64571] = { id = 64571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tazavesh: Suchen und nicht zerstören" }
quests[64579] = { id = 64579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leer, aber wertvoll", description = "Die großen Metallsphären, die die Landschaft von Zereth Mortis übersäen, sind verbrauchte Schmieden, die während des Schöpfungsprozesses entsorgt wurden.\n\nDiese leeren Metallhüllen enthalten noch Reste des Schöpfungsmaterials, die für uns nützlich sein können.\n\nVerwendet meinen Schmiedeanzapfer in der Nähe dieser Metallsphären, um übriggebliebene Neopartikel einzusammeln. Und vielleicht findet Ihr auch noch andere hilfreiche Protomaterialien!", sourceObjective = "Sammelt 40 übriggebliebene Neopartikel von Progenitorschmieden mithilfe von Firims Schmiedeanzapfer ein.", progress = "Habt Ihr die Materialien schon gesammelt?", completion = "Ausgezeichnete Arbeit, {name}. Diese Ressourcen werden uns ein ganzes Stück weiterbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64581] = { id = 64581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:\n\nFür {name}, ein ganz besonderer {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64582] = { id = 64582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yuni-Test" }
quests[64592] = { id = 64592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Historienschutz", description = "Die Fremden haben die Sande gestört. Wir haben keinen Zugriff auf die Terraformingaufzeichnungen mehr, die wir benötigen, um die notwendigen historischen Informationen zu sammeln.\n\nKönnt Ihr uns unterstützen?\n\nHelft Mai Obet beim Einsammeln der historischen Aufzeichnungen in den Endlosen Sanden.", sourceObjective = "Helft Mai Obet, 6 Terraformingaufzeichnungen in den Endlosen Sanden zu untersuchen.", completion = "Wir haben die benötigten Aufzeichnungen archiviert. Danke für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[64597] = { id = 64597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanktum der Herrschaft - Und täglich grüßt das Schlundgetier", description = "Ich spüre Kel'Thuzads Präsenz in diesen Hallen. Sammelt Splitter seines Phylakteriums, damit ich einen neuen Weg in seine Kammern öffnen kann.\n\nVier Splitter sollten reichen. Wir wollen ja schließlich nicht, dass er zurückkehrt, oder?", sourceObjective = "Sammelt 4 Phylakteriumsplitter von Kel'Thuzad im Sanktum der Herrschaft auf dem Schwierigkeitsgrad 'Normal'.", progress = "Vier Splitter sollten es uns ermöglichen, diese Kammer zu betreten.", completion = "Das sollte uns helfen, leichter in seine Kammer zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64598] = { id = 64598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanktum der Herrschaft - Und täglich grüßt das Schlundgetier", description = "Ich spüre Kel'Thuzads Präsenz in diesen Hallen. Sammelt Splitter seines Phylakteriums, damit ich einen neuen Weg in seine Kammern öffnen kann.\n\nVier Splitter sollten reichen. Wir wollen ja schließlich nicht, dass er zurückkehrt, oder?", sourceObjective = "Sammelt 4 Phylakteriumsplitter von Kel'Thuzad im Sanktum der Herrschaft auf dem Schwierigkeitsgrad 'Heroisch'.", progress = "Vier Splitter sollten es uns ermöglichen, diese Kammer zu betreten.", completion = "Das sollte uns helfen, leichter in seine Kammer zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64599] = { id = 64599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanktum der Herrschaft - Und täglich grüßt das Schlundgetier", description = "Ich spüre Kel'Thuzads Präsenz in diesen Hallen. Sammelt Splitter seines Phylakteriums, damit ich einen neuen Weg in seine Kammern öffnen kann.\n\nVier Splitter sollten reichen. Wir wollen ja schließlich nicht, dass er zurückkehrt, oder?", sourceObjective = "Sammelt 4 Phylakteriumsplitter von Kel'Thuzad im Sanktum der Herrschaft auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Vier Splitter sollten es uns ermöglichen, diese Kammer zu betreten.", completion = "Das sollte uns helfen, leichter in seine Kammer zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64607] = { id = 64607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tazavesh: Harte Geschäfte", description = "Ah, meine Arbeit steht Euch wirklich fabelhaft zu Gesicht. Ihr seid das Sinnbild der Legitimität!\n\nUnd da ich Euch nun meine Talente zur Verfügung gestellt habe, werdet Ihr mir mit den Euren dienen. Trefft Euch in der Güldenen Landung mit meinem Geschäftspartner Fe'tajid und bietet ihm Eure Unterstützung an.\n\nIch freue mich schon darauf, von Eurem Erfolg zu hören.", sourceObjective = "Sucht Au'manals Geschäftspartner auf und bietet ihm Eure Unterstützung an.", completion = "Unsere Bemühungen, die Zo zu täuschen, scheinen fehlgeschlagen zu sein. Dasselbe gilt aber auch für ihre Versuche, Euch zu töten... Also alles kein Problem, oder?\n\nAber vielleicht wäre ja eine großzügigere Belohnung angebracht. Bitte nehmt das hier an, und seid Euch meiner aufrichtigsten Dankbarkeit versichert.", sourceObjectiveStatus = "unverified-source-field" }
quests[64639] = { id = 64639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk", sourceObjective = "Auf dem Schildchen am Geschenk steht:\n\nFrohe Feiertage, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[64640] = { id = 64640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "AubriesTestQuestForJeff" }
quests[64641] = { id = 64641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöses Grünzeug", description = "Es gibt eine strahlende Kraft, die von dort oben ausgeht. Ich werde von ihr angezogen wie eine Motte vom Licht!\n\nIch will mir das auf jeden Fall mal ansehen. Wollt Ihr mich nicht begleiten? Das wird bestimmt ein großer Spaß!", sourceObjective = "Besucht das Ungezähmte Grün zusammen mit Glimmerstöckchen.", completion = "Wir sind der Kreis Koh von den Jiro.\n\nWir sind hier, um dieses Land wiederherzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64642] = { id = 64642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumen in den Ruinen", description = "Dieser Ort war für lange Zeit verlassen. Die Vegetation hat das Land überwuchert.\n\nWir müssen uns in die Blühende Gießerei begeben, um es in Ordnung zu bringen.\n\nBis dahin: Räumt in dem Gebiet auf. Entfernt die Abweichler, die im Laufe der Zeit entstellt wurden.", sourceObjective = "Tötet 15 Kreaturen im Ungezähmten Grün.", completion = "Das ist ein guter Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[64643] = { id = 64643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrott wird wieder flott", description = "Die Blühende Gießerei hat diesen Bereich geschaffen. Sie erhält die Automas, die Kreaturen und die Pflanzen.\n\nDiese Überwucherung ist ihre Schuld.\n\nWir müssen die Gießerei betreten, um dieses Land wiederherzustellen. Der Konstruktor kann sich einen Weg hindurchbahnen, wenn er wieder funktioniert.\n\nViele Automas in diesem Gebiet befinden sich schon lange im Stillstand. In ihrem Inneren könnt Ihr ein paar brauchbare Teile finden.", sourceObjective = "Findet 8 Automainnereien von zurückgelassenen Automas im Ungezähmten Grün.", progress = "Mit Eurer Hilfe werden wir die frühere Pracht dieses Ortes wiederherstellen.", completion = "Das sollte funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[64644] = { id = 64644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Spritzer der Äonen", description = "Ich weiß nicht wirklich viel über diesen Ort oder seine Bewohner, aber ich kenne mich mit Magie aus! Ich kann die uralte Macht der Gewässer in unserer Nähe spüren.\n\nVielleicht hilft uns das weiter?\n\nLasst uns mal diesen Teich begutachten!", sourceObjective = "Helft Glimmerstöckchen, Wasser aus dem Teich im Ungezähmten Grün zu entnehmen.", progress = "<Das Automa verharrt inaktiv.>", completion = "<Eine kleine Öffnung in der Kreatur scheint perfekt dafür geeignet zu sein, etwas von dem mystischem Wasser hineinzugeben.>", sourceObjectiveStatus = "unverified-source-field" }
quests[64645] = { id = 64645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moment der Wahrheit", description = "Unser Konstruktor ist bereit.\n\nWir werden jetzt die Blühende Gießerei wieder in Gang setzen und dieses Land zurücksetzen.\n\nEin Neuanfang steht bevor.", sourceObjective = "Folgt den Jiro der Koh im Ungezähmten Grün.", completion = "Auf zur Gießerei.", sourceObjectiveStatus = "unverified-source-field" }
quests[64646] = { id = 64646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochfahren", description = "Wir müssen die Energie der Gießerei wiederherstellen, um sie nutzen zu können. Konduktoren kanalisieren die Energie, damit wir sie einsetzen können.\n\nWir wissen, wie man mit den Konduktoren umgeht. Macht den Weg frei, dann können wir alles erneuern.", sourceObjective = "Aktiviert 4 Konduktoren in der Blühenden Gießerei.", completion = "Diese Automas sollten sich nicht so verhalten.\n\nSie sind wunderschön. Seltsam. Neu.\n\nWir müssen uns beraten, bevor wir fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[64647] = { id = 64647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsames Innenleben", description = "<Seltsamerweise ist der Samen im Innern des Automa noch sehr lebendig.\n\nIst das bei allen der Fall?>", sourceObjective = "Sammelt 3 windende Saaten von den Automas in der Blühenden Gießerei.", progress = "Sie sind wirklich sehr ungewöhnlich.", completion = "<Koh Shira untersucht das Teil des Automa, das von lebenden Ranken umschlungen ist.>\n\nDas kann nicht sein.\n\nIn Automas gibt es keine Ranken. Aber in diesen Automas schon.\n\nDas ist... wunderschön.", sourceObjectiveStatus = "unverified-source-field" }
quests[64648] = { id = 64648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ernten, was gesät wurde", description = "Wir haben dem Konstruktor gesagt, dass wir die Gießerei nutzen werden, um dieses Land zurückzusetzen.\n\nWir müssen ihn aufhalten und die neuen Automas beschützen.", sourceObjective = "Besiegt den aufgeladenen Konstruktor.", completion = "Etwas über neue Kreaturen zu lernen, die von lebendigem Wachstum durchdrungen sind... Das klingt ganz nach meinem Geschmack!\n\nIch denke, ich werde bei ihnen bleiben und sehen, wie ich helfen kann... Vielleicht kann ich ja auch ihre Sprache erlernen.\n\nDanke für dieses gemeinsame Abenteuer!", sourceObjectiveStatus = "unverified-source-field" }
quests[64650] = { id = 64650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyänenseele", description = "<Die Hyänenseele ist feurig und agil. Ihr könnt jetzt die Gestalt der Hyäne nutzen.>", sourceObjective = "Bringt die Hyänenseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, die Hyäne. Ihr könnt ihre Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64651] = { id = 64651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobraseele", description = "<Die Kobraseele ist begierig und hat einen ausgeprägten Beschützerinstinkt. Ihr könnt jetzt die Gestalt der Kobra nutzen.>", sourceObjective = "Bringt die Kobraseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, die Kobra. Ihr könnt ihre Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64654] = { id = 64654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Ben Howell", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[64706] = { id = 64706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Motivation", description = "In diesem Sand liegen haufenweise Riesen, <Sterblicher/Sterbliche>. Aber ich glaube, dass wir sie wiederbeleben können.\n\nWir können dazu die kleineren Automas einsetzen, die sich in der Wüste verstecken. Verwendet meinen Motivator, um sie für unsere Zwecke einzuspannen. Wenn wir genug davon zusammenbekommen, kann ihre Energie die dieser besiegten Ungetüme wieder auffüllen, damit sie unsere Streitkräfte verstärken.\n\nBringt mir so viele davon wie möglich, damit wir sie einsetzen können!", sourceObjective = "Bringt 6 motivierte Automas zu Firim.", completion = "Gut gemacht, Sterblicher! Schon bald werden wir die Ergebnisse Eurer Mühen sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64709] = { id = 64709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein teuflischer Weg durch die Zeit", description = "Ein verderbender Stern wirft sein Licht auf das Land und droht allen mit einem feurigen Untergang. Der Stern verrät jene, die nach dem Licht streben, denn sein rotes Leuchten verhüllt, anstatt zu erhellen.\n\nUnter seinem Einfluss eröffnen sich neue Wege... zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[64710] = { id = 64710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüsternder Teufelsflammenkristall", description = "Der Kristall gibt Impulse eines unheimlichen, teufelsfeuergrünen Leuchtens ab. Wenn Ihr ihn in der Hand haltet, hört Ihr ein schwaches Echo kehliger Dämonenstimmen. Die Worte sind zwar wirr, aber eines ist erkennbar und wird oft wiederholt: Dalaran.\n\nVielleicht kann Euch jemand in der schwebenden Stadt über den Verheerten Inseln mehr über den Kristall und seinen Zweck erzählen.", sourceObjective = "Bringt den flüsternden Teufelsflammenkristall zu Aridormi in der Stadt Dalaran, die über den Verheerten Inseln schwebt.", completion = "Der kommt direkt dorthin zurück, wo er hingehört. Danke, dass Ihr ihn mir gebracht habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[64713] = { id = 64713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleinteilige Angelegenheit", description = "Die Kugeln helfen uns, das Gelände für die Entwicklung der Schmiede vorzubereiten. Die Magie der Kugeln zieht aber die Verschlinger an. Sie zerreißen das Metall, um an sie zu gelangen. Wir müssen die Überreste einsammeln.\n\nSucht nach den Fragmenten um die Kugeln herum. Bringt sie zu uns.", sourceObjective = "Sammelt 30 Kugelfragmente.", progress = "Konntet Ihr die Fragmente finden? Wir brauchen ganze Menge davon.", completion = "Genug, um eine kleine Kugel instandzusetzen. Das wird reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64717] = { id = 64717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Material der Schöpfung", description = "Die großen Metallsphären, die die Landschaft von Zereth Mortis übersäen, sind verbrauchte Schmieden, die während des Schöpfungsprozesses entsorgt wurden.\n\nDie Sphären in der Nähe der Schmiede der Nachleben enthalten Spuren von Materialien, die nur an diesem Ort vorkommen.\n\nIch habe meinen Schmiedeanzapfer modifiziert, um diese Materialien einzusammeln. Verwendet ihn in der Nähe der Schmieden, die ich identifiziert habe. Die seltenen eidolischen Fragmente finden sich häufig bei den größten Progenitorschmieden.", sourceObjective = "Sammelt 10 eidolische Fragmente und 300 Stück schwaches Enigmet.", progress = "Habt Ihr gesammelt, was wir brauchen?", completion = "Ich werde sie sofort einsetzen. Sie werden Saezurah und den Automas helfen, den Auswirkungen der Herrschaftsmagie zu widerstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64718] = { id = 64718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüssel zum Sieg", description = "Das Lied ist... unvollständig. Harmonie ist erforderlich. Findet die Seher. Schickt sie, um dem Kreis zu dienen.\n\nDie Schlundgebundenen haben die Schlüssel, die binden. Nehmt die Schlüssel, befreit sie.", sourceObjective = "Befreit 6 Automaseher aus ihren Zellen.", completion = "Der Chor findet zusammen. Schon bald werden unsere Stimmen verschmelzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64720] = { id = 64720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg bereiten", description = "<Schlundgänger/Schlundgängerin>! Meine Späher berichten, dass die Schlundgebundenen zwei Automaorakel unter ihre Kontrolle gebracht haben, damit diese sie im Kampf unterstützen. Diese Orakel werden mit Sicherheit unsere Strategie und unsere Vorhaben vorhersagen, wenn sie die Gelegenheit dazu bekommen.\n\nWir müssen diese beiden Orakel ausschalten, bevor wir die Gruften betreten. Ohne sie werden die Truppen der Schlundgebundenen unsere Aktionen erst verstehen, wenn wir sie schon ausgeführt haben.\n\nNehmt Emeni mit. Sie ist mehr als bereit für den Kampf.", sourceObjective = "Tötet das Orakel Zoketh und das Orakel Voraxxi.", completion = "Perfekt umgesetzt, {name}. Der Verlust dieser beiden Orakel wird die Schlundgebundenen im Dunkeln stochern lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64722] = { id = 64722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An der Pforte des Todes", description = "Jetzt ist es so weit, <Sterblicher/Sterbliche>. Die Streitkräfte, die Ihr zusammengestellt habt, sollten ausreichen, um die Reihen der Schlundgebundenen zu durchbrechen und die Gruften zu erreichen. Der Weg ins Innere steht damit allerdings noch nicht offen. Die Schlundgebundenen haben den Eingang verbarrikadiert.\n\nKbato wird Euch in die Schlacht tragen. Erledigt die Schlundgebundenen und zerstört die Geräte, die die Barriere mit Energie versorgen.", sourceObjective = "Reitet auf Kbato in den Kampf, besiegt die schlundgebundenen Truppen in den Endlosen Sanden und öffnet so den Weg in die Gruften der Ewigen.", completion = "Bei den Ersten... Ich hätte mir nie träumen lassen, diesen Ort einmal mit eigenen Augen zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64723] = { id = 64723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Projekt zur Wiederherstellung", description = "Ohne einen Richter kommen die Schattenlande ihrer eigentlichen Bestimmung nicht mehr nach. Die Seelen strömen ziellos in den Schlund.\n\nWie Saezurah bemerkte, müsste Zereth Mortis ganz einfach ein neues Wesen schaffen, das den Platz der Richterin einnimmt. Aber ich vermute, dass die Streitkräfte des Kerkermeisters dem Land so sehr zugesetzt haben, dass dies nicht mehr möglich ist.\n\nEs ist an der Zeit, die Dinge selbst in die Hand zu nehmen und den Schattenlanden wieder Stabilität zu verleihen! Sprecht mit Saezurah, um herauszufinden, wo wir damit anfangen.", sourceObjective = "Sprecht mit Saezurah.", completion = "Die Pakte werden sicherlich Hilfe schicken, wenn wir sie darum bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64725] = { id = 64725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unverzeihliches Eindringen", description = "Die Dunkelheit erzeugt Dissonanz in diesen Hallen. Die Schlundgebundenen entziehen der Luft das Leben und fügen im Gegenzug nur Leid hinzu. Das darf nicht sein.\n\nUm das Lied wiederherzustellen, ist Stille erforderlich. Die Schlundgebundenen müssen ausgelöscht werden.", sourceObjective = "Eliminiert 6 beherrschte Automas und 3 Verderber der Dunkelseher.", completion = "Die goldene Stunde der Stille. Ein Raum, in dem die Schöpfung beginnen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[64726] = { id = 64726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In guter Ordnung", description = "Essenzen der uralten Seelen, die manipuliert wurden... Sie bluten aus jedem Raum. Die Hallen müssen wiederhergestellt und der Strom der Seelen umgelenkt werden.\n\nDie Kugeln bergen den Schlüssel. Versiegelt die Durchbrüche und stellt den Fluss wieder her, damit das Gefäß wieder gefüllt werden kann.", completion = "Den Atem angehalten in Erwartung... Schon bald wird die Seele verschmelzen und das Lied der Schöpfung beginnen." }
quests[64727] = { id = 64727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der unendliche Kreis", description = "Die Schöpfung ruft... Könnt Ihr sie hören? Doch die Dunkelheit lauert dort unten und besudelt die uralte Melodie.\n\nUm neu zu formen, muss der Frieden wiederhergestellt werden. <Der Gänger/Die Gängerin> muss gehen und beschützen.\n\nEs gibt viel zu tun. Geht voran.", sourceObjective = "Begleitet Saezurah zum Zentrum der Gruften der Ewigen.", completion = "Unsere Stimmen werden in der lauernden Dunkelheit gedämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[64728] = { id = 64728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergessene Bekannte", description = "Es ist Zeit. Das Lied wird neues Leben bringen. Sagt mir, wenn Ihr bereit seid, anzufangen.", sourceObjective = "Schließt das Ritual ab.", completion = "Die Dissonanz bleibt. Ein reiner Ton ist vonnöten. Stellt den Kreis wieder her.", sourceObjectiveStatus = "unverified-source-field" }
quests[64729] = { id = 64729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lange Auswirkungen", description = "Dieses Lied ist vollendet und die Harmonie wiederhergestellt. Doch Zereth Mortis wird immer noch von Zwietracht heimgesucht.\n\nDissonanz verweilt immer noch außerhalb dieser Mauern. Wir müssen gehen, bevor sie uns findet.\n\nSprecht mit dem, den Ihr Firim nennt. Er wird Euch den Weg weisen.", sourceObjective = "Kehrt zur Höhle des Verbannten zurück.", completion = "Ich kann kaum glauben, was wir alles erreicht haben... Wahrlich ein denkwürdiger Tag. Ohne Euch hätten wir das nie erreicht, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[64730] = { id = 64730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wendepunkt", description = "Eine atemlose Pause. Eine Melodie klingt nach. Der Zyklus wartet auf eine Stimme.\n\n<Ihr seid Euch nicht sicher, was Saezurah damit meint. Vielleicht solltet Ihr versuchen, das Ritual noch einmal durchzuführen, beginnend mit dem Gefäß und den Sehern.>", sourceObjective = "Untersucht das Gefäß und die Automaseher.", completion = "Ich sage es nicht gern, aber ich fürchte... dass wir versagt haben, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[64731] = { id = 64731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für alle Seelen", description = "Wenn der Strom der Seelen einfach so in den Schlund fließt, ohne dass ein Richter ihn eindämmt, werden sich die Schattenlande nie erholen.\n\nSo darf es nicht enden. Euch fällt doch gewiss etwas ein, oder?", sourceObjective = "Findet einen Weg, einen neuen Richter zu erschaffen.", progress = "Dieser Augenblick ist ausgesprochen wichtig.", completion = "Eine neue Stimme erklingt im Chor. Der Kreislauf geht immer weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[64733] = { id = 64733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe aus der Ferne", description = "Wenn wir die schlundgebundenen Kräfte besiegen wollen, werden wir die Hilfe aller Pakte benötigen.\n\nIch werde mit den Kyrianern sprechen. Ihr und Pelagos könnt mit den anderen reden. Aber fragt Firim, bevor Ihr geht, ob es eine Möglichkeit gibt, auch die Erleuchteten für uns zu gewinnen.", sourceObjective = "Sprecht mit Repräsentanten der Erleuchteten, Venthyr, Nekrolords und Nachtfae.", completion = "Angesichts der Stärke der Streitkräfte des Paktes und der Hilfe der Automas sollten wir in der Lage sein, die Gruften zu erreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[64739] = { id = 64739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zovaals Umklammerung", description = "Ich erinnere mich an dieses Metall. Ich habe es gesehen, als ich von Schlundmagie berührt war. Als ich abgetrennt wurde...\n\nIch werde Euch zeigen, wo das passiert ist. Folgt mir. Ich werde Euch meine Geschichte erzählen.", sourceObjective = "Folgt Hanoa der Verbannten und hört Euch ihre Geschichte an.", completion = "Es ist schlimmer, als ich befürchtet hatte. Viel schlimmer.", sourceObjectiveStatus = "unverified-source-field" }
quests[64741] = { id = 64741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheitsprüfung", description = "Ich verstehe das nicht. Das sind meine Brüder und Schwestern! Wie können sie so sorglos sein, wenn sowohl die gierigen Kartelle als auch die Schlundgebundenen so nah sind?\n\nIhre Schutztechnologie ist veraltet. Sie wird die Gefahr nicht fernhalten können. Wenn ich sie schon nicht zur Flucht überreden kann, muss ich wenigstens die Sicherheit am Aufenthaltsort ihrer Wahl gewährleisten.\n\nIch will meine Freunde nicht noch einmal verlieren.\n\nAm Rand des Schilds sollten sich vier versteckte Leitungen befinden. Nehmt dieses Set. Damit könnt Ihr sie untersuchen und, falls nötig, reparieren.", sourceObjective = "Untersucht die Schildleitungen um die Zuflucht herum.", completion = "Ich wusste es. Kartell Xy hat sich an der Verteidigung der Zuflucht zu schaffen gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[64742] = { id = 64742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spuren der Manipulation", description = "Der Schutzschild wurde also sabotiert. Natürlich steht das skrupellose Kartell Xy in der ersten Reihe, wenn es um einen Versuch geht, von diesem Land zu profitieren.\n\nSeine Gier hat uns alle in noch größere Gefahr gebracht. Wir müssen es aufhalten. Lasst uns gemeinsam nach Zeichen für sein Eindringen suchen.", sourceObjective = "Findet Hinweise auf die Anwesenheit des Kartells Xy.", completion = "Das Kartell Xy ist in der Nähe.", sourceObjectiveStatus = "unverified-source-field" }
quests[64743] = { id = 64743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xyso sind sie hier?", description = "Wir können sie nicht sehen, aber ich bin mir sicher, dass das Kartell Xy hier seine Basis errichtet hat.\n\nIrgendetwas muss Xy speziell in dieses Gebiet von Zereth Mortis gelockt haben. Wir müssen herausfinden, was es ist, wenn wir unsere Freunde hier schützen wollen.\n\nVorräte werden von seiner Abschirmung nicht ganz so gut verborgen. Seht nach, welche Informationen Ihr aus den Sachen gewinnen könnt.", sourceObjective = "Sammelt 10 verdächtige Papiere.", progress = "Wir müssen herausfinden, was das Kartell Xy hier vorhat.", completion = "Oh, das Kartell hat also gedacht, es könnte seine Pläne mit einem Code verbergen? Wartet mal kurz, das sollte nicht lange dauern...", sourceObjectiveStatus = "unverified-source-field" }
quests[64744] = { id = 64744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enttarnte Mittler", description = "Spürt Ihr auch diese Veränderung in der Luft? Es hält sich vielleicht verborgen, aber das Kartell Xy ist in der Nähe.\n\nGlücklicherweise kenne ich die Geräte, mit deren Hilfe sich seine Mitglieder tarnen. Hier, nehmt das. Wenn Ihr es auf dem Boden platziert, werden ihre Agenten in der Nähe sichtbar... zumindest für eine gewisse Zeit.\n\nHaltet sie auf, und sei es, dass Ihr ihnen das Leben nehmen müsst.", sourceObjective = "Tötet 12 Agenten des Kartells Xy außerhalb der Zuflucht.", completion = "Ihr Tod ist bedauerlich, aber wir müssen die Zuflucht schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64745] = { id = 64745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstlose Verwahrung", description = "Hier gab es einst eine Vielzahl an Automas. Sie sangen, bauten verschiedene Dinge und dienten den Zielen der Ersten. Aber dann schlachteten die Eindringlinge aus dem Schlund sie alle ab.\n\nDie letzten Automas, die gefallen sind, haben etwas Wichtiges an einem nahe gelegenen Ort bewacht.\n\nIch habe gesehen, wie einer der verfluchten Schlundgebundenen ein Gerät neben der Tür gestohlen hat. Die Ältesten sagen, dass wir uns nicht mit Artefakten befassen sollen, aber wäre es ein Vergehen, wiederzuholen, was uns gestohlen wurde?", sourceObjective = "Holt das gestohlene Artefakt im Anordnungsindex zurück und bringt es wieder dorthin, wo es hingehört.", completion = "Dieses Automa lebt noch! Aber es ist sehr schwach.", sourceObjectiveStatus = "unverified-source-field" }
quests[64758] = { id = 64758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt dem Anführer", description = "Wir haben die Tür zum Schlummernden Gewölbe sofort versiegelt, als wir ankamen. Es ist ein Heiligtum, eine Wiege für alles, was hier wertvoll ist. Die ihm innewohnende Macht sollte nicht von uns berührt werden.\n\nWenn der Anführer von Kartell Xy es geschafft hat, die Schutzschilde zu überwinden, während wir von der Schönheit dieses Ortes abgelenkt waren, dann graut mir vor der Vorstellung, welchen Schaden es bereits angerichtet hat.\n\nSchnell! Wir müssen zum Schlummernden Gewölbe, um für seine Sicherheit zu sorgen.", sourceObjective = "Untersucht das Schlummernde Gewölbe.", completion = "Nein! Was hat der verdammte Narr nur mit der Konsole angestellt?!", sourceObjectiveStatus = "unverified-source-field" }
quests[64759] = { id = 64759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchaus noch nützlich", description = "Dieses Automa hat sich hier versteckt! Ich vermute, dass es uns wohl nicht helfen wird.\n\nIch schlage das nicht gern vor, aber wenn der Diener Euch mit dieser Einrichtung in Verbindung bringt, ist er uns gegenüber vielleicht etwas aufgeschlossener.\n\nWenn Ihr könnt, dann kopiert die Glyphen, die auf ähnlichen Automas draußen eingraviert sind. Jene, die vom Schlund berührt wurden, sind unbrauchbar, aber ich habe von meinem Aussichtspunkt aus ein paar gefallene Automas im Sand gesehen, die unberührt sind.", sourceObjective = "Sammelt Glyphen von 6 ausgelaugten Dienern im Anordnungsindex.", completion = "Ich hoffe, dies wird unseren Freund hier dazu bringen, uns als Verbündete zu betrachten. Mögen die Ersten uns vergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[64760] = { id = 64760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technische Schwierigkeiten", description = "Die Konsole ist außer Kontrolle! Wir müssen sie irgendwie reparieren!\n\nVielleicht geht das ja mit diesen Knöpfen?", sourceObjective = "Drückt die Knöpfe auf der Konsole im Schlummernden Gewölbe.", completion = "Vielen Dank für Eure Hilfe, Schlundgänger.\n\nIch muss nach Oribos zurückkehren. Ich werde Kartell Al berichten, dass unsere Freunde nicht verloren, sondern erleuchtet sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[64761] = { id = 64761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kernkompetenz", description = "Das arme Ding.\n\nWas heilig ist, sollte nicht gestört werden, aber... werden die Ältesten uns verurteilen, wenn wir ihm helfen zu überleben? Es geht um Erhalt, nicht um Einmischung.\n\n...hoffe ich.\n\nWir können es wieder aufladen. Benutzt diesen erschöpften Kern als Leitung. Vielleicht haben die größeren wilden Animate in den nahen Sanden genug Energie, um ihn aufzuladen.", sourceObjective = "Ladet einen erschöpften Automakern auf, indem Ihr wilden Kreaturen im Anordnungsindex Energie entzieht.", completion = "Dieses einsame Ding wird bald wieder stark sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[64762] = { id = 64762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederleben des Stärkeren", description = "Dieser Kern strotzt nur so vor Energie!\n\nVerwendet den geladenen Kern, um das Automa wiederzubeleben. Hoffentlich sieht es uns nicht mehr als Bedrohung an.\n\nSeid vorsichtig. Wir sind nicht dazu bestimmt, die Macht der Ersten zu beherrschen.", sourceObjective = "Erweckt den versteckten Diener im Anordnungsindex wieder zum Leben.", completion = "Unterstützung ist eingetroffen. Die Wiederherstellung kann beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64763] = { id = 64763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wartungsmodus", description = "Der Architekt hat folgende Aufgaben festgelegt: \n\nUnversehrt bleiben.\n\nDas Protoformrepositorium wiederherstellen, wenn die Gefahr vorbei ist.\n\n<Der Sterbliche/Die Sterbliche> kennt die Chiffren. <Der Sterbliche/Die Sterbliche> hilft bei den Aufgaben.\n\nDie Einstimmung der Energieschaltpulte ist erforderlich. Jedes Terminal benötigt einen Kodex. Eindringlinge haben die nötigen Kodexe gestohlen.\n\nGeht.", sourceObjective = "Stimmt 4 Energieschaltpulte im Anordnungsindex ab.", completion = "Die Aufgaben wurden begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64766] = { id = 64766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zügiger Zugang", description = "Allein der Architekt besitzt die für die Wiederherstellung erforderliche Wiederherstellungsmatrix. Der Architekt wird das Protoformrepositorium wiederherstellen.\n\n<Der/Die> Sterbliche erhält Zugang zur Kammer der Gestaltung und wird den Architekten über die neusten Fortschritte informieren. Der Architekt wird das Repositorium wiederherstellen.\n\nDie Aufgabe wird in Kürze abgeschlossen.", sourceObjective = "Findet den Protoarchitekten in der Kammer der Gestaltung und besorgt Euch eine Wiederherstellungsmatrix.", progress = "Der Architekt wird uns helfen.", completion = "Die Wiederherstellungsmatrix ist vorhanden. Der Architekt ist abwesend. Verlust des Architekten wird vermerkt.\n\nTrotzdem bleibt die Wiederherstellung des Repositoriums unerlässlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[64767] = { id = 64767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Lied", description = "Diener sind nicht stark genug, um Repositorien wiederherzustellen. Der Abschluss dieser Aufgabe ist dennoch unerlässlich.\n\n<Der/Die> Sterbliche muss in der Nähe bleiben, um den Wiederherstellungsprozess zu sichern.\n\nFolgt mir.", sourceObjective = "Bleibt nahe bei Kodah, während Ihr Gegner abwehrt, um das Protoformrepositorium einzunehmen.", completion = "Ich hätte auf die Ältesten hören sollen! Das ist alles meine Schuld!", sourceObjectiveStatus = "unverified-source-field" }
quests[64768] = { id = 64768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtritzels Artefaktjagd" }
quests[64771] = { id = 64771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erleuchteter Exodus", description = "Hallo, <mein Bester/meine Beste>!\n\nVor langer Zeit hat das Kartell Al eine Expedition in dieses Gebiet geschickt, die inzwischen als verloren gilt. Ich kam nach Zereth Mortis, um mein gespaltenes Kartell vor den Gefahren des Schlundes zu beschützen, die mir vorausgeeilt sind.\n\nEndlich habe ich meine alte Freundin gefunden! Aber trotzdem will sie nicht, dass ich sie in Sicherheit bringe.\n\nVielleicht lassen sich die anderen überzeugen. Würdet Ihr es versuchen?", sourceObjective = "Sprecht mit den Erleuchteten im Bereich der Zuflucht.", completion = "Wenn sie sich nicht überzeugen lassen, muss jemand sie beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64772] = { id = 64772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gebrochene Kreis", description = "Hier arbeiten die Jiro des Kreises Olea. Wir machen...\n\n<Die Jiro hält einen Moment inne.>\n\nSie... machen neues Land und Wesen für die Schmiede.\n\nDie Verschlinger griffen an, aber einige Jiro haben überlebt. Ihr müsst sie finden. Sagt ihnen, sie sollen sich vor der Höhle im Norden versammeln. Ich sorge dafür, dass der Weg frei ist.\n\nSagt ihnen nicht, dass ich Euch geschickt habe. Sie werden mich nicht sehen wollen.", sourceObjective = "Findet alle überlebenden Jiro und überzeugt sie, sich vor der Höhle zu versammeln.", completion = "Danke, dass Ihr die Überlebenden gefunden habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[64773] = { id = 64773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlungenwerden vermeiden für Jiro", description = "Die Verschlinger haben angegriffen. Sie haben die Wächter überrannt. Sie suchen immer noch nach Nahrung.\n\nWir sind nicht sicher. Verringert die Zahl der Verschlinger.\n\nSo werden wir nicht verschlungen.", sourceObjective = "Dünnt die Zahl der Verschlinger an der Terrasse der Formgebung aus.", completion = "Weniger Verschlinger, weniger wahrscheinlich werden wir verschlungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64775] = { id = 64775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Schlund auf anders", description = "In der Höhle ist ein Verschlinger. Er erzeugt einen Riss. Das sollte in Zereth Mortis unmöglich sein.\n\nGeht in die Höhle und vernichtet den Verschlinger. Sucht nach Hinweisen. Findet heraus, wie er einen Riss öffnen kann.\n\nSeid vorsichtig. Dieser ist anders als der Rest. Er hat die Magie der Ersten absorbiert. So etwas ist bisher nie geschehen. Seid auf alles gefasst.\n\nIch bleibe hier und beschütze die Jiro.", sourceObjective = "Tötet den Auflöser und durchsucht ihn nach Hinweisen.", progress = "Ist der Verschlinger vernichtet? Habt Ihr irgendwelche Hinweise gefunden?", completion = "Eine neue Art Verschlinger. Beunruhigend. Hoffentlich gibt es nicht noch mehr.\n\nUnd was dieses mysteriöse Metall angeht... So etwas habe ich schon einmal gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64778] = { id = 64778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rissanalyse", description = "Verschlinger sind ein Problem. Risse sind ein größeres Problem.\n\nSie bringen mehr Verschlinger. Wir müssen sie schließen. Dafür brauchen wir Informationen.\n\nNehmt das Crescendium. Analysiert damit die Risse. Bringt uns dann die Informationen.", sourceObjective = "Analysiert 6 verzerrte Risse.", completion = "Diese Informationen werden uns helfen. Zeigen uns, wie wir die Risse schließen. Weniger Risse bedeuten weniger Verschlinger.", sourceObjectiveStatus = "unverified-source-field" }
quests[64779] = { id = 64779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfundweise Fleisch", description = "Automas beseitigen Bedrohungen für uns. Aber alle Automas sind fort. Wir müssen uns selbst helfen. Wir brauchen Magie.\n\nVerschlinger haben die Kugelmagie verschlungen. Jetzt sind sie verzerrt und entstellt. Aber auch voller Magie.\n\nBringt uns Verschlingerfleisch. Wir extrahieren die Magie. Wir brauchen sie, um die Verschlinger zu besiegen.", sourceObjective = "Sammelt 30 entstelltes Fleisch von Verschlingern bei Zovaals Umklammerung.", progress = "Verschlinger sollten niemals diese Magie verschlingen.", completion = "Dieses Fleisch hat {name} gesammelt?\n\n\n\nDas muss reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64780] = { id = 64780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Schlundstahl, kein Problem", description = "Zereth Mortis ist heilig. Hier sollten keine Risse entstehen. Irgendetwas erschafft sie.\n\nDas Metall, das Ihr gefunden habt, enthält Schlundmagie. Verschlinger erschaffen damit Risse. So umgehen sie unseren Schutz.\n\nÜberall in dieser Gegend liegen Schlundstahlsplitter verstreut. Nehmt diese Splitter. Werft sie von unseren Klippen. Sorgt dafür, dass die Verschlinger damit keine Risse mehr erschaffen.", sourceObjective = "Hebt 4 Schlundstahlsplitter an und werft sie von den Klippen.", completion = "Ohne Schlundstahl keine Risse. Ist zwar nicht viel, aber es hilft.", sourceObjectiveStatus = "unverified-source-field" }
quests[64783] = { id = 64783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelmond-Tanzparty", description = "Simon sagt: \"Bereit zum Tanz?\" Immer heran und zeigt, was Ihr könnt, {class}.\n\nDie Regeln sind einfach. Euer Gegner lässt ein paar stylishe Moves los und Ihr müsst sie nachtanzen.\n\nVerdient Euch genug Auszeichnungen und kommt zum alten Simon zurück. Eins noch: Je schwerer der Gegner, desto mehr Auszeichnungen winken Euch.\n\nSimon sagt: \"Bereit für die Herausforderung?\"", sourceObjective = "Erringt Auszeichnungen bei dem Tanzwettbewerb.", progress = "Simon sagt: \"Zeigt mir, was Ihr draufhabt.\"", completion = "Simon sagt: \"Das waren ein paar heiße Moves, {name}.\" \n\nSimon ist beeindruckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[64784] = { id = 64784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "9.0 Rated PvP Incentive - Shadowlands Season 2 Exclusive Mount" }
quests[64785] = { id = 64785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grün außer Rand und Band", description = "Seit unserer Ankunft hier ist das Ungezähmte Grün ein Rätsel, das nur auf seine Lösung wartet. Während diese Wesen so ohne Aufgabe Amok laufen, breiten sich diese üppigen Grünpflanzen überall aus.\n\nVon diesen Wesen lassen sich bestimmte einige wertvolle Forschungsdaten sammeln.\n\nStellt die Elementarwesen mit einer Eindämmungsfalle ruhig. Sobald sie ruhig sind, untersucht Ihr sie, um die Daten zu sammeln.", sourceObjective = "Untersucht Gaiagantik und 12 Geomentare, um Forschungsdaten zu erhalten.", completion = "Diese Informationen helfen, aber ich fürchte, die Ruinen bleiben weiterhin ein Rätsel!", sourceObjectiveStatus = "unverified-source-field" }
quests[64794] = { id = 64794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist die halbe Schlacht", description = "{name}, Ihr solltet Shandris begleiten und die Streitmacht der Schlundgebundenen aus dem Osten infiltrieren. Was auch immer Ihr an Informationen findet, wird unsere weiteren Schritte bestimmen.\n\nGebt auf Euch acht. Wir wissen nicht, was Euch dort erwartet.", sourceObjective = "Trefft Euch mit Shandris bei Provis Strata.", completion = "Da seid Ihr ja.\n\nIhre Manöver sind sehr seltsam. Es ist fast, als wäre der Hauptteil ihrer Streitmacht gar nicht hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[64796] = { id = 64796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchkämmt die Sande", description = "Bisher haben wir nicht viel gesehen, und das liefert mir auch so gut wie keine Informationen über unsere Feinde. Wir müssen uns wohl etwas genauer umsehen.\n\nAuf Euren Befehl kann ich uns beide vor neugierigen Augen verbergen. Aber haltet Euch von den Schreckenslords fern. Ihre Augen sind scharf und können sogar eine getarnte Jägerin entdecken.", sourceObjective = "Erkundet Provis Strata mit Shandris Mondfeder.", progress = "Je weniger Aufmerksamkeit wir erregen, desto besser.", completion = "Wir haben ihr nächstes Ziel gefunden. Lasst uns schnell zu unseren Verbündeten zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[64797] = { id = 64797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harmonie und Zwietracht", description = "Diese Obelisken müssen der Schlüssel zu Zovaals Plan sein. Auch wenn wir ihren Zweck nicht genau kennen, sollten wir wohl lieber verhindern, dass sich die Schlundgebundenen an ihnen zu schaffen machen.\n\nIch werde Hochlord Bolvar unterrichten. Geht Ihr zu Darion Mograine. Er muss seine Verteidigung nach diesen Informationen aufbauen.", sourceObjective = "Sprecht mit Darion Mograine bei Provis Terra.", completion = "Noch halten unsere Verteidigungslinien dem Feind stand, aber ich fürchte, ohne Eure Hilfe werden wir die Schlacht verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[64798] = { id = 64798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir meistern", description = "Jetzt verstehe ich. Alle von uns, die von der Herrschaft berührt waren, konnten eine besondere Macht für sich nutzen. Ob nun Edelmut oder Rache, diese Macht gab uns die Kraft, zu widerstehen.\n\nNach allem, was ich durchgemacht habe, darf ich nicht vergessen, dass ich noch hier bin.\n\nUnd wenn noch jemand zu Sylvanas steht, dann muss ich daran glauben, dass auch noch jemand zu mir steht.\n\nIch bin bereit für einen neuen Versuch. Was auch immer mich erwartet, ich werde stärker sein.", sourceObjective = "Besiegt die schlundgebundene Monstrosität und ladet den letzten Splitter auf.", completion = "All die Splitter sind nun von dem Widerstand erfüllt, den wir aus unserer Erfahrung mit der Herrschaft schöpfen konnten.\n\nEs war nicht einfach. Für keinen von uns. Aber ich bin stolz darauf, was wir zusammen erreicht haben.\n\nUnd was den Rest angeht: Unsere Zukunft liegt nun in den Händen des Primus.", sourceObjectiveStatus = "unverified-source-field" }
quests[64799] = { id = 64799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zerbrochene Krone", description = "Unsere Freunde sind mit einem bekannten Gesicht aus dem Mausoleum der Ersten zurückgekehrt.\n\nAnduin... Was hat er alles erlitten.\n\nAber wie schwer und schmerzhaft es auch sein mag, wir müssen herausfinden, was er weiß. Der Kerkermeister hat uns den Weg im Mausoleum versperrt, und wir laufen Gefahr, selbst der Herrschaft zum Opfer zu fallen.\n\nEr ist unsere beste Chance.", sourceObjective = "Sprecht mit Anduin Wrynn in der Geometrischen Höhle.", progress = "Wir müssen Zovaal besiegen, sonst ist alles verloren.", completion = "All das Leid, das er ertragen hat...\n\nEs wird nicht einfach, all das zu überwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[64800] = { id = 64800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere letzte Option", description = "Zovaal hat unsere Verfolgung ausgebremst. Wenn wir ihn besiegen wollen, müssen wir einen Weg finden, der Herrschaft zu trotzen.\n\nAber dafür müssen wir verstehen, wie sie funktioniert.\n\nDie Herrschaft ist das Werk des Primus von Maldraxxus. Er kann uns gewiss mehr darüber sagen.\n\nIch habe Taelia gebeten, ein Stück von dem Helm der Herrschaft nach Zereth Mortis zu bringen. Ich schaudere bei dem Gedanken, was alles geschehen könnte, würde ich ihn wieder tragen...\n\nReden wir über unsere nächsten Schritte.", sourceObjective = "Hört Euch den Plan an.", completion = "Mir gefällt diese Option ebenso wenig wie Taelia, aber wir müssen die Herrschaft sicher einsetzen können, um ihr zu trotzen.\n\nZuerst müssen wir sicherstellen, dass der Helm noch wirkt. Auf uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[64801] = { id = 64801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Älteste Eru", description = "Nachdem uns die Erleuchteten jetzt vertrauen, habe ich eine Menge über ihre Forschungen in Zereth Mortis gelernt.\n\nSie wissen mehr, als sie preisgeben möchten. Aber oft lassen sie all dieses Wissen ungenutzt. Vielleicht können wir eingreifen, wo sie lediglich beobachten.\n\nIn einer abgeschiedenen Ecke namens Lichtung der Lexik findet Ihr die Älteste Eru. Vielleicht kann sie uns helfen, die Sprache der Ersten richtig einzusetzen.\n\nGeht zu ihr und findet heraus, ob sie uns helfen wird.", sourceObjective = "Findet die Älteste Eru vor der Lichtung der Lexik.", completion = "Wie war das? Ihr wollt wissen, ob es hier etwas gibt, das Euch helfen kann, der Magie der Schlundgebundenen zu widerstehen?\n\nIhr habt Glück, Fremdling. Ich weiß zufällig, dass dieser Ort eine Bibliothek ist. Und Bibliotheken sind wunderbar, wenn Ihr nach Wissen sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[64802] = { id = 64802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Vergangenheit", description = "Ich habe die Herrschaft erschaffen, um Zovaal zu bestrafen.\n\nMein Zorn formte dieses Werk und nun bezahlen wir den Preis für meinen Hochmut. Selbst die Ewigen irren sich von Zeit zu Zeit.\n\nAber noch ist nicht alle Hoffnung verloren.\n\nNehmt die Hälfte des Helms der Herrschaft und erprobt ihn an einem Eurer Verbündeten. Sollte er noch genug Macht enthalten, könnt Ihr ihn auch an anderer Stelle in Zereth Mortis testen.", sourceObjective = "Erprobt den zerbrochenen Helm der Herrschaft an Darion Mograine.", progress = "Wir geben nicht auf. Wir müssen Zovaal aufhalten.", completion = "Auch wer sich von der Herrschaft befreit hat, ist nicht vollständig dagegen immun.\n\nAber in dieser Geschichte gibt es vielleicht etwas, das uns helfen kann.\n\nLasst mich darüber nachdenken.\n\nKonzentriert Ihr Euch fürs Erste auf die Wesen von Zereth Mortis. Findet heraus, warum sie widerstandsfähiger sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[64803] = { id = 64803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Probieren gehört zum Studieren", description = "Die Wesen von Zereth Mortis lebten hier schon lange, bevor ich die Herrschaft erschuf.\n\nWir haben gesehen, welche Auswirkung Zovaals Streitmacht auf sie hat, aber ich glaube, es gibt noch mehr zu lernen.\n\nWendet den Helm auf die Bewohner von Zereth Mortis an und findet alles über ihre natürliche Widerstandskraft heraus.", sourceObjective = "Erprobt den zerbrochenen Helm an Wesen in Zereth Mortis.", progress = "Ihr habt ein von Herrschaft erfülltes Objekt, ohne dass sie Euch überwältigt? Interessant.", completion = "Die höher entwickelten Wesen können der Herrschaft länger widerstehen?\n\nAber natürlich. Das hätte ich Euch auch sagen können. Es dreht sich alles um die Sprache!", sourceObjectiveStatus = "unverified-source-field" }
quests[64804] = { id = 64804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kryptischer Katalog", description = "Das hier ist ein Repositorium verschiedener Texte. Hmmm? Wovon sie handeln? Ich habe keine Ahnung!\n\nIch habe mich lediglich ihrer Katalogisierung und Ordnung verpflichtet. Dies ist jetzt wichtiger denn je, nachdem diese Invasion das Gleichgewicht von ganz Zereth Mortis stört! Wir müssen beschützen, was wir bisher alles gefunden haben.\n\nIhr könnt helfen. Geht zu der Lichtung und merkt Euch die Phrasen dort, anschließend treffen wir uns unten in der Grotte. Dort ist etwas, mit dem Ihr Euren Helm weiter testen könnt.", sourceObjective = "Lernt die Phrasen auf der Lichtung der Lexik auswendig.", completion = "Dieser Ort ein wahres Wunder.\n\nMein ganzes Leben könnte ich hier verbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64805] = { id = 64805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unwissenschaftliche Methode", description = "Die Sprache der Ersten ist nicht statisch wie die meisten Sprachen. Sie entwickelt sich weiter.\n\nWesen wie die Wächter sind offensichtlich höher entwickelt als einfache Puttriden. Dank ihrer komplexeren Gedanken entwickeln sie eine Resistenz gegen die beherrschende Magie der Invasoren.\n\nAber Ihr solltet Euch nicht allein auf mein Wort verlassen. Wir können das ausprobieren!\n\nIn der Grotte befindet sich ein Lexikothekar. Erfüllt ihn mit den Phrasen, die Ihr auswendig gelernt habt, und probiert dann Euren Helm aus.", sourceObjective = "Erprobt den zerbrochenen Helm an dem aktivierten Lexikothekar und beobachtet das Ergebnis.", completion = "Seht Ihr! Es hat viel länger gedauert, bis die Herrschaft die ursprüngliche Aufgabe des Lexikothekars außer Kraft gesetzt hat.\n\nNatürlich konnte er sich letztendlich nicht widersetzen, aber für Euch ist das ein echter Erfolg.\n\nKeine Sorge, ein anderes Automa wird seinen Platz einnehmen. Es muss immer einen Lexikothekar geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[64806] = { id = 64806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hort der Erinnerung", description = "Ich glaube, ich weiß, was uns in der Bastion erwartet. Das wird nicht leicht.\n\nMit dieser Hälfte des Helms haben wir den ersten Teil von dem, was wir brauchen, um der Herrschaft zu widerstehen. Aber auch einige von uns haben durch sie gelitten. Und es überlebt.\n\nAuf gewisse Weise hat uns diese Erfahrung gezeichnet. Uns alle.\n\nIn dieser Erfahrung muss es etwas geben, mit dem wir uns von Zovaals Einfluss befreien können.\n\nLasst uns zur Bastion gehen und die Kammer der Ersten Reflexion aufsuchen.", sourceObjective = "Trefft Euch mit Hochlord Bolvar in der Kammer der Ersten Reflexion in der Bastion.", completion = "Gut, da seid Ihr ja.\n\nWir haben alle versammelt, die in der Vergangenheit unter der Herrschaft gelitten haben. Einige erst vor kurzer Zeit.\n\nAlle haben es überstanden, nicht immer unbeschadet, aber wir sind ungebrochen. Genau darauf kommt es an.", sourceObjectiveStatus = "unverified-source-field" }
quests[64807] = { id = 64807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir vergessen wollen", description = "Die Sprache der Progenitoren ist zwar hilfreich, aber uns wird etwas anderes helfen, die Macht der Herrschaft zu brechen.\n\nEin unbezwingbarer Wille.\n\nWir, die wir all das schon einmal durchlitten und überlebt haben, besitzen diese Resistenz und wir werden sie in jeden einzelnen der Splitter übertragen.\n\nDer Primus hat mir versichert, dass es funktioniert. Und da wir keine anderen Optionen haben, ist dies der einzige Weg.\n\nIch hoffe, es ist all das Leid wert.", sourceObjective = "Helft bei dem Ritual und erfüllt die Splitter der Herrschaft.", completion = "Ich fühle mich... leichter. Aber ich kann nicht vergessen, was mich hergeführt hat und was immer noch zu tun ist.\n\nIch hoffe, Taelia wird sich an das erinnern, was sie gesehen hat... An den Mann, der ich jetzt bin. Nicht an eine einsame und isolierte Gestalt, sondern an jemanden, der zum Wohle aller das tut, was notwendig ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[64808] = { id = 64808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was uns stark macht", description = "Hätte ich nur früher von diesem Ort erfahren. Hier könnte man die furchtbarste Dunkelheit aus dem Innern vertreiben, Erinnerungen erforschen und auch ausmerzen...\n\nIch bin bereit, alles zu tun, um dabei zu helfen, Zovaal zu besiegen. Um jeden Preis.\n\nDies ist der einzige Weg.", sourceObjective = "Helft bei dem Ritual und erfüllt die Splitter der Herrschaft.", progress = "Man braucht mehr als rohe Kraft, um das zu tun, was wirklich nötig ist.", completion = "Ich glaube, jetzt verstehe ich.\n\n<Anduin sammelt seine Kräfte.>\n\nIch bin bereit, es noch einmal zu versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64809] = { id = 64809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Hälfte der Gleichung", description = "Die Theorie des Primus über die Sprache der Ersten hat sich bewahrheitet.\n\nAber es reicht vielleicht trotzdem nicht.\n\nWährend der Primus seine Planung abschließt, werden wir in den Endlosen Sanden weitere Stücke dieser Macht für den Helm suchen.\n\nDarion, Taelia und ich treffen Euch dort und helfen gegen die Schlundgebundenen.", sourceObjective = "Reist zum Verlassenen Rundblick.", completion = "Der Feind scheint übermächtig, aber mit der Kraft unserer Waffen und der Macht des zerbrochenen Helms haben wir eine Chance.\n\nIch gebe allerdings zu, da meine Tochter hier kämpft, bin ich etwas vorsichtiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[64810] = { id = 64810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterdrücken und zerstören", description = "Was wir suchen, liegt in den Gewölben der Endlosen Sande. Die erreichen wir nur, wenn wir stark bleiben. Und auf keinen Fall schaffen wir das allein.\n\nWir werden die Schlundgebundenen zusammen vernichten.\n\nIch freue mich schon, dass wir sie endlich direkt angreifen.\n\nVergesst nicht, dass sie für den zerbrochenen Splitter aus dem Helm der Herrschaft anfällig sind.", sourceObjective = "Tötet Schlundgebundene in den Endlosen Sanden.", progress = "Welch herrliche Einöde.", completion = "Gut gemacht.\n\nHoffen wir, dass der Helm ab heute nie wieder als Waffe eingesetzt werden muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[64811] = { id = 64811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Ausgrabung", description = "Die Älteste Eru hat gesagt, dass sich hier draußen die besonders komplexen Beispiele für die Sprache der Ersten finden.\n\nWir müssen uns den Weg zu den Gewölben freikämpfen und dann den Helm erfüllen, sobald wir die Phrasen gefunden haben.\n\nMal ganz unter uns, ich hätte nie gedacht, dass ich mal an der Seite meines Vaters kämpfen würde. Aber hier steht buchstäblich alles auf dem Spiel und ich fühle, dass mein Platz genau hier ist.\n\nIch bin bereit, wenn Ihr es seid.", sourceObjective = "Sammelt die unverständlichen Phrasen.", completion = "Wir haben es geschafft. Die zerbrochene Hälfte des Helms enthält nun die fortgeschrittensten Teile der Macht der Ersten, die wir finden konnten.\n\nWir haben es fast geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[64812] = { id = 64812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiede der Herrschaft", description = "Wir haben alle Teile, die wir brauchen. Die zerbrochene Hälfte des Helms ist mit der komplexesten Sprache der Ersten erfüllt und die Splitter mit unseren Erinnerungen.\n\nUnserem Willen, der Herrschaft zu trotzen.\n\nJetzt muss der Primus nur noch den Helm neu schmieden und wir können selbst seine geballte Macht nutzen.\n\nIch weiß, das ist gefährlich, aber auch unsere einzige Hoffnung.", sourceObjective = "Reist zur Oubliette des Runenmetzes in Torghast.", completion = "Wie passend, dass der Ort, an dem ich gefangen war, nun die Wiege unserer Freiheit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[64813] = { id = 64813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone der Willen", description = "Als ich die Herrschaft erschuf, konnte ich nicht voraussehen, wie viel Leid sie den Reichen zufügen würde. Nicht nur den Schattenlanden, sondern auch Eurer Welt.\n\nEs wird Zeit, dass wir den Helm, das Symbol dieser Magie, neu schmieden. Aber nicht zu dem Zweck, dem er einst diente.\n\nEr wird ein Zeichen für die Stärke und den Willen sein, den Ihr und Euresgleichen besitzt, und uns helfen, Zovaal endlich zu bezwingen.", sourceObjective = "Schmiedet den Helm der Herrschaft neu.", progress = "Es gibt kein Zurück.", completion = "Noch nie habe ich solch eine Macht gespürt. Wir haben etwas völlig Neues geschaffen.\n\nDas hier ist der Schlüssel zum Sieg über Zovaal.", sourceObjectiveStatus = "unverified-source-field" }
quests[64814] = { id = 64814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Schmiede", description = "Unsere Streitkräfte schlagen sich bisher recht gut, aber wir haben das Gebiet noch nicht gesichert. Wir könnten etwas Hilfe brauchen, um die feindlichen Reihen auszudünnen.\n\nDas sollte für Euch kein Problem sein, <Schlundgänger/Schlundgängerin>.", sourceObjective = "Tötet 8 Streitkräfte der Schlundgebundenen.", completion = "Wir müssen wachsam bleiben. Niemand darf unsere Verteidigung durchbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64815] = { id = 64815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir reiten zusammen", description = "Die vier Pakte haben ihre Kräfte mit denen der Automas vereint.\n\nLeider wurden einige unserer Soldaten verwundet oder versprengt und können nicht hierher zurückkehren.\n\nEs wäre uns eine große Hilfe, wenn Ihr ihnen helfen könntet.", sourceObjective = "Helft 5 Paktkämpfern.", completion = "Je weniger Verluste wir hier erleiden, desto länger können wir die Stellung halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64816] = { id = 64816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An der Schwelle der Realität", description = "Die Zeit ist gekommen, Zovaal in das Herz der Schattenlande zu folgen.\n\nWir müssen nach Zereth Mortis zurückkehren und das hier beenden.", sourceObjective = "Kehrt nach Zereth Mortis zurück.", completion = "Es gibt in Zereth Mortis noch viel zu tun, bevor die Schattenlande endlich von Zovaals Einfluss befreit sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[64817] = { id = 64817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direkt vor der Nase", description = "Dieses Geräusch! Es kam aus der Richtung des Obelisken bei Provis Flora.\n\nDas ist unmöglich. Niemand ist an uns vorbeigekommen. Schnell, {name}! Mir nach!", sourceObjective = "Verteidigt den Obelisken bei Provis Flora.", progress = "Wir müssen uns beeilen!", completion = "Sie haben sich getarnt. Das könnte übel für uns enden.", sourceObjectiveStatus = "unverified-source-field" }
quests[64818] = { id = 64818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung wäre hilfreich", description = "Die Schreckenslords haben unsere Reihen weitgehend infiltriert. Bolvar muss erfahren, was hier geschehen ist.\n\nIch kann meinen Posten nicht verlassen. Schnell, überbringt ihm die Neuigkeiten. Vielleicht fällt ja auch dem Rat der Erleuchteten etwas ein.", sourceObjective = "Sprecht mit Bolvar Fordragon in der Zuflucht.", completion = "Mograine wird die Streitkräfte bekommen, die er braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[64820] = { id = 64820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Schuld, Eure Pflicht", description = "Provis Fauna wird normalerweise von autonomen Konstrukten kontrolliert, aber wir haben gehört, dass sie nicht mehr funktionieren.\n\nLaut diesen Berichten seid Ihr für die Änderungen an diesen Knotenpunkten verantwortlich. Das heißt auch, Ihr müsst das wieder geradebiegen. Nehmt dieses Abstimmgerät, damit sollte es gehen. Und wenn sie repariert sind, macht Euch nicht noch einmal an ihnen zu schaffen.", sourceObjective = "Repariert 5 Verteidigungsknotenpunkte.", completion = "Nachdem die Verteidigung jetzt wieder funktioniert, weichen die Schlundgebundenen hoffentlich zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[64821] = { id = 64821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts ist wahr", description = "Wenn wir es mit Schreckenslords zu tun haben, dann könnten sie sich als alles Mögliche tarnen... Auch als Einwohner von Zereth Mortis. Zum Glück haben wir genau das Richtige, um ihre Illusionen zu neutralisieren.\n\nDurchsucht die Felder und überprüft die Automas. Wenn Ihr einen Schreckenslord findet, erledigt ihn.", sourceObjective = "Findet und tötet 4 Schreckenslordsaboteure.", completion = "Das sollte ihre Pläne verlangsamen. Gut gemacht, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[64822] = { id = 64822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommunikationsprobleme", description = "Mograines Bitte um Verstärkung ist ungewöhnlich. Wir wollten dieses Gebiet bereits verstärken und haben schon drei Einheiten zu ihm geschickt.\n\nAber es klingt so, als wäre nicht eine angekommen. Sucht doch mal ihre Kommandanten und sorgt dafür, dass sie Mograine erreichen.", sourceObjective = "Gebt drei Paktkommandanten neue Befehle.", completion = "Sie sagen, Ihr hättet ihnen ihre alten Befehle gegeben? Seltsam.", sourceObjectiveStatus = "unverified-source-field" }
quests[64823] = { id = 64823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duell der Doppelgänger", description = "Irgendetwas stört mich an dieser ganzen Sache. Nach Eurem Bericht würde ich auf Sabotage aus unseren eigenen Reihen tippen... oder auf das Werk weiterer Schreckenslords.\n\nWenn Schreckenslords ihre Finger im Spiel haben, könnte der Obelisk in Gefahr sein! Also los, wenn wir uns zu lange hiermit aufhalten, ist es vielleicht zu spät!", sourceObjective = "Findet die Schlundgebundenen am Kreis der Gedanken.", progress = "Die Zeit drängt hier.", completion = "Mal'Ganis...\n\nWir verlieren diesen Wettlauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[64824] = { id = 64824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf um die Schmiede", description = "Wir sind so schnell hergekommen, wie wir konnten. Anduin wurde nahe des Bauwerks in der Mitte des Landes gesehen, das alle Schmiede der Nachleben nennen.\n\nDer Kerkermeister wird zweifellos bald bei ihm sein. Wir müssen sofort aufbrechen.", sourceObjective = "Begebt Euch mit Jaina zur Schmiede der Nachleben.", completion = "Anduin...\n\nWir werden Euch irgendwie retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[64825] = { id = 64825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuflucht gesucht", description = "Ich weiß nicht weiter.\n\nWir können Zovaal und Anduin nicht folgen. Ich öffne ein Portal zurück zur Zuflucht. Dort besprechen wir, wie es weitergeht.", sourceObjective = "Kehrt mit Jaina und Baine zur Zuflucht zurück.", completion = "Wir finden einen Weg, ihnen in das Mausoleum zu folgen. Bis dahin solltet Ihr Euch auf unsere dringenderen Probleme konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[64829] = { id = 64829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Tahli", description = "Nach einer Ewigkeit des Friedens hat der Schlund das Leid nach Zereth Mortis gebracht. Einer unserer Akolythinnen, Tahli, fällt es besonders schwer, die jüngsten Ereignisse zu verarbeiten. Sie hat uns vor einiger Zeit verlassen und ist noch nicht zurückgekehrt.\n\nWürdet Ihr nach ihr sehen? Zuletzt war sie auf dem Weg zu den Ruinen, die unter dem Sand begraben liegen.", sourceObjective = "Sucht Tahli in der Nähe des Anordnungsindex.", completion = "Selbst jetzt ist dieser Ort wunderschön.", sourceObjectiveStatus = "unverified-source-field" }
quests[64830] = { id = 64830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit dem Licht der Erleuchteten", description = "Das Schicksal von Sylvanas ist nicht gerade von oberster Priorität für mich.\n\nDer Kerkermeister hat die Harmoniekanäle zerstört, damit wir ihm nicht folgen.\n\nVielleicht besitzen die wissenshungrigen Erleuchteten Mittler einige Informationen über diese Kanäle, die uns helfen. Doch die Hilfe der Mittler hat oft mehr als einen Haken.\n\nTut, was immer sie verlangen. Wir müssen einfach mehr erfahren.", sourceObjective = "Überredet die Ältesten der Zuflucht, Euch zu helfen.", completion = "Zereth Mortis birgt alle Antworten, die Ihr sucht.\n\nWenn Ihr wisst, wo Ihr suchen müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[64831] = { id = 64831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste der Ersten", description = "Einige Überreste der von den Schlundgebundenen verursachten Zerstörung finden sich vielleicht noch in Provis Esper. Diese Überreste liefern uns gewiss einen Hinweis, wie sich dieser Kerkermeister verfolgen lässt.\n\nGehen wir gemeinsam auf diese Jagd. Ich erkenne die Magie der Ersten, wenn wir uns in ihrer Nähe befinden.", sourceObjective = "Sammelt 3 Leitungsüberreste.", progress = "Haben wir alle Überreste gefunden?", completion = "Leider nur inaktive Überreste.\n\nAber verliert nicht gleich die Hoffnung, mein Guter!", sourceObjectiveStatus = "unverified-source-field" }
quests[64832] = { id = 64832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung von Provis Esper", description = "Verschlinger haben Provis Esper überrannt und schwirren überall herum wie hungrige Vespiden.\n\nSie zerstören dort alle Automas, was ganz und gar nicht im Sinne der Ersten ist. Es wird Zeit für eine Läuterung.\n\nVernichtet einige von ihnen, zu unserer Sicherheit und zum Schutz der natürlichen Ordnung.", sourceObjective = "Tötet 20 unersättliche Milben, 5 seelenverdorrte Fresser und 2 Realitätsbrecher.", progress = "Habt Ihr Provis Esper geläutert?", completion = "Weitere Verschlinger werden kommen, aber für den Moment habt Ihr diese Sorge etwas gelindert.", sourceObjectiveStatus = "unverified-source-field" }
quests[64833] = { id = 64833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Summe des Ganzen", description = "Die anderen Ältesten folgen einer strikten Interpretation, wie das Werk der Ersten zu ehren ist.\n\nIch bin nicht so unflexibel. Letztendlich wollen wir doch alle dasselbe.\n\nKehren wir dorthin zurück, wo Ihr den Kerkermeister zuletzt gesehen habt.", sourceObjective = "Trefft Euch mit der Ältesten Ara über Provis Esper.", completion = "Dort unten wimmelt es nur so von Verschlingern. Aber Ihr schafft das, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[64834] = { id = 64834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es wurde Licht", description = "Seht nur, {name}. Die Überreste leuchten schwach!\n\nSie müssen auf irgendetwas in der Huld des Pilgers reagieren.\n\nFindet heraus, was genau diese Reaktion verursacht!", sourceObjective = "Findet, auf was die Leitungsüberreste reagieren.", progress = "Die Überreste haben auf diesen Translokator reagiert? Unglaublich!", completion = "Die Überreste und der Translokator sind also auf irgendeine Art verbunden. Aber wie?\n\nWelche Funktion sie auch früher hatten, jetzt sind sie vollkommen inaktiv.", sourceObjectiveStatus = "unverified-source-field" }
quests[64835] = { id = 64835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ränkespiele", description = "Ich bin gerannt, durch das Dornengestrüpp mit den Peitschern dicht auf meinen Fersen.\n\nMeine Pilgerbrüder hatten nicht so viel Glück. Während meiner Flucht konnte ich ihre furchtbaren Schmerzensschreie hören.\n\nIhr müsst einen Weg hinein finden. Rettet sie, {name}!", sourceObjective = "Rettet 5 vermisste Pilger.", completion = "Ich kann Euch nicht genug danken, dass Ihr all diese Pilger gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[64836] = { id = 64836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Stumpf und Stiel", description = "Die Katalysatorstationen waren früher so friedlich. Seit einer halben Ewigkeit kommen die Pilger hierher, um die Wunder der Ersten zu bestaunen. Aber hier ist es nicht länger sicher. Grund- und Gnadenlos hat der Kultivator einige unserer Brüder getötet.\n\nIhr müsst ihn vernichten.\n\nDie anderen Ältesten würden mir wahrscheinlich widersprechen. Die anderen Ältesten liegen falsch.", sourceObjective = "Tötet den Kultivator.", completion = "Den Kultivator zu vernichten war die richtige Entscheidung.", sourceObjectiveStatus = "unverified-source-field" }
quests[64837] = { id = 64837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Pilgers Reise", description = "Die Huld des Pilgers ist eine heilige Stätte für die Erleuchteten. Die Ältesten dort wissen sehr viel über die Schöpfungen der Ersten.\n\nDort finden wir auch einige Antworten zu diesen merkwürdigen Überresten, die wir gefunden haben.\n\nWir treffen uns bei der Huld des Pilgers. Es ist gar nicht weit von hier.", sourceObjective = "Trefft Euch mit der Ältesten Ara bei der Huld des Pilgers.", completion = "Willkommen bei der Huld des Pilgers.", sourceObjectiveStatus = "unverified-source-field" }
quests[64838] = { id = 64838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ein Pilger ist, ist auch ein Weg", description = "Wenn sich die Überreste wiederherstellen lassen, dann sollte jemand in der Huld des Pilgers wissen, wie das geht.\n\nFangt bei dem Ältesten Nirav an. Ich hoffe, er ist gewillt, Euch zu helfen. Er wirkt heute etwas besorgt und abgelenkt.\n\nWenn Ihr fertig seid, findet Ihr mich in der Stadt.", sourceObjective = "Sprecht mit Bewohnern der Huld des Pilgers.", progress = "Habt Ihr schon mit den Erleuchteten in der Huld des Pilgers gesprochen?", completion = "Feroz ist unsere beste Chance? Und er ist mit den anderen Pilgern zusammen verschwunden?\n\nWir sollten uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[64839] = { id = 64839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurzel des Problems", description = "Ich vermute, wir können die Wachstumsenergie in diesen Pflanzen für unsere Zwecke nutzen, aber ich brauche ein paar frische Proben.\n\nIhr könnt das energiegeladene Pflanzenmaterial von den Peitschern sowie von den von Ranken überwucherten Automas in der Nähe sammeln oder auch von denen in den Katalysatorstationen.", sourceObjective = "Sammelt energiegeladenes Pflanzenmaterial.", progress = "Habt Ihr das energiegeladene Pflanzenmaterial gefunden?", completion = "Die Wurzeln strotzen nur so vor Wachstumsenergie.", sourceObjectiveStatus = "unverified-source-field" }
quests[64840] = { id = 64840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungezügeltes Wachstum", description = "Diese Wachstumsenergie ist äußerst ungewöhnlich. Ich würde gern mehr über ihre Auswirkungen auf die örtlichen Automas erfahren.\n\nSammelt die replizierende Essenz von den inaktiven Automas in den Katalysatorgärten.\n\nBringt sie mir dann her, damit ich sie studieren kann.", sourceObjective = "Sammelt 12 Einheiten replizierende Essenz.", progress = "Habt Ihr die replizierende Essenz?", completion = "Hm... Repliziert sich schnell, bis sie den Wirt getötet hat.\n\nDas ist eher eine Krankheit als ein Geschenk!", sourceObjectiveStatus = "unverified-source-field" }
quests[64841] = { id = 64841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwer geladen", description = "Das schwebende Konstrukt über uns ist der Schöpfungskatalysator.\n\nIch komme nicht näher an ihn heran. Der Turm ist mit Progenitorenergie überladen. Der Weg dorthin wäre reiner Selbstmord.\n\nIn den Gärten gibt es Konsolen, um diese Energie zu entladen. Erledigt das.", sourceObjective = "Entladet die überschüssige Energie des Schöpfungskatalysators.", completion = "Gut gemacht, Schlundgänger!", sourceObjectiveStatus = "unverified-source-field" }
quests[64842] = { id = 64842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furiose Flora", description = "Diese Wächterautomas werden alles abschießen, was sich dem Schöpfungskatalysator zu nähern versucht.\n\nMein Vorschlag: Warum nicht Feuer mit Feuer bekämpfen? Oder eher, die Schöpfungen der Ersten mit der Schöpfungsenergie der Ersten.\n\nIch konnte meine Theorie noch nicht ausführlich testen, aber dieser Trank sollte Euch genug Kraft verleihen, sie zu zerstören... Idealerweise, ohne dass Ihr dabei der Schöpfungsenergie zum Opfer fallt.", sourceObjective = "Trinkt Feroz' Gebräu und zerstört die Automas in den Katalysatorgärten.", completion = "Ich finde, ihre eigene Wachstumsenergie gegen sie einzusetzen, entbehrt nicht einer gewissen Ironie.", sourceObjectiveStatus = "unverified-source-field" }
quests[64843] = { id = 64843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüsseldienst", description = "Nachdem die aufgebrachten Automas jetzt Ruhe geben, ist es fast geschafft.\n\nWir werden Euch und Eure erleuchtete Begleitung zum Schöpfungskatalysator bringen.\n\nDer Rest liegt dann bei Euch.", sourceObjective = "Stellt den Translokatorschlüssel am Schöpfungskatalysator wieder her.", completion = "Wir haben es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[64844] = { id = 64844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Pilgerfahrt", description = "Ihr habt viele Pilger gerettet und ich habe Euren Zugang zum Mausoleum wiederhergestellt. Damit ist unser Handel abgeschlossen und auch meine Pilgerschaft.\n\nAber Eure Reise geht weiter.\n\nKehrt zum Rundblick hinter der Huld des Pilgers zurück und öffnet den Translokator.\n\nHabt Dank, {name}. Dieses Abenteuer war... erleuchtend.", sourceObjective = "Kehrt zum Rundblick hinter der Huld des Pilgers zurück.", progress = "Hören wir uns an, was sie zu sagen haben.", completion = "Der nächste Schritt ist gewaltig. Seid Ihr bereit, {name}?", sourceObjectiveStatus = "unverified-source-field" }
